// ---------------------------------------------------------------- strings

#define PATHLEN 600
static unsigned slen(const char *s) { unsigned n = 0; while (s[n]) n++; return n; }
static void scpy(char *d, unsigned cap, const char *s) { unsigned i = 0; while (s[i] && i + 1 < cap) { d[i] = s[i]; i++; } d[i] = 0; }
static void cat(char *d, unsigned cap, const char *s) { unsigned n = slen(d); if (n < cap) scpy(d + n, cap - n, s); }
static char low(char c) { return c >= 'A' && c <= 'Z' ? c + 32 : c; }
static int sameText(const char *a, const char *b) { while (*a && low(*a) == low(*b)) a++, b++; return !*a && !*b; }
static int sameTextN(const char *a, const char *b, unsigned n) { for (unsigned i = 0; i < n; i++) if (low(a[i]) != low(b[i]) || !a[i]) return 0; return 1; }
static int contains(const char *hay, unsigned n, const char *needle) {
    unsigned m = slen(needle);
    for (unsigned i = 0; i + m <= n; i++) { unsigned j = 0; while (j < m && hay[i + j] == needle[j]) j++; if (j == m) return 1; }
    return 0;
}
static void join(char *out, const char *dir, const char *name) { scpy(out, PATHLEN, dir); cat(out, PATHLEN, "\\"); cat(out, PATHLEN, name); }

// ---------------------------------------------------------------- language
// The window in every language the game has (build/lang_setup.h, made by lang.py
// from lang/*.json). English is the key: T("Install") is that text in the current
// language, or the English if it has none. N_ marks text translated where it's shown.
#define N_(s) s
#include "build/lang_setup.h"
static volatile int langIndex; // into LANG_CODE; 0 is English
static int sameStr(const char *a, const char *b) { while (*a && *a == *b) a++, b++; return *a == *b; }
static const char *T(const char *en) {
    if (langIndex) for (int i = 0; i < TR_COUNT; i++) if (TR_KEY[i] && sameStr(TR_KEY[i], en)) return TR_TEXT[langIndex][i] ? TR_TEXT[langIndex][i] : en;
    return en;
}
// "de", "de-DE", "pt_BR", "zh-Hant", "zh-TW"... -> its place in LANG_CODE, or -1.
static int langOf(const char *tag) {
    char t[16] = {0};
    for (int i = 0; tag[i] && i < 15; i++) t[i] = low(tag[i] == '_' ? '-' : tag[i]);
    if (t[0] == 'z' && t[1] == 'h' && (!t[2] || t[2] == '-')) { // Chinese: traditional for Taiwan, Hong Kong and Macau
        int hant = sameTextN(t + 2, "-hant", 5) || sameTextN(t + 2, "-tw", 3) || sameTextN(t + 2, "-hk", 3) || sameTextN(t + 2, "-mo", 3);
        scpy(t, sizeof(t), hant ? "zh-hant" : "zh-hans");
    }
    for (int i = 0; i < LANG_COUNT; i++) {
        const char *c = LANG_CODE[i]; int k = 0;
        while (c[k] && low(c[k]) == t[k]) k++;
        if (!c[k] && (!t[k] || t[k] == '-')) return i;
    }
    return -1;
}
// Windows' display language.
static const char *systemLang(void) {
    WORD id = GetUserDefaultUILanguage();
    switch (id & 0x3FF) {
    case 0x04: return id == 0x0404 || id == 0x0C04 || id == 0x1404 || id == 0x7C04 ? "zh-Hant" : "zh-Hans";
    case 0x07: return "de"; case 0x0A: return "es"; case 0x0C: return "fr"; case 0x10: return "it";
    case 0x11: return "ja"; case 0x12: return "ko"; case 0x13: return "nl"; case 0x15: return "pl";
    case 0x16: return "pt"; case 0x19: return "ru"; case 0x1D: return "sv"; case 0x1F: return "tr"; case 0x22: return "uk";
    }
    return "en";
}

// ---------------------------------------------------------------- files

static int exists(const char *p) { return GetFileAttributesA(p) != 0xFFFFFFFF; }
static char *readAll(const char *p, DWORD *n) {
    HANDLE f = CreateFileA(p, 0x80000000 /*GENERIC_READ*/, 1 | 2 /*share read/write*/, 0, 3 /*OPEN_EXISTING*/, 0x80, 0);
    if (f == (HANDLE)-1) return 0;
    DWORD size = GetFileSize(f, 0), got = 0;
    char *b = HeapAlloc(GetProcessHeap(), 0, (U64)size + 1);
    if (b && (!ReadFile(f, b, size, &got, 0) || got != size)) { HeapFree(GetProcessHeap(), 0, b); b = 0; }
    CloseHandle(f);
    if (b) { b[size] = 0; *n = size; }
    return b;
}
static int writeAll(const char *p, const void *d, DWORD n) {
    HANDLE f = CreateFileA(p, 0x40000000 /*GENERIC_WRITE*/, 0, 0, 2 /*CREATE_ALWAYS*/, 0x80, 0);
    if (f == (HANDLE)-1) return 0;
    DWORD put = 0; BOOL ok = WriteFile(f, d, n, &put, 0) && put == n;
    CloseHandle(f);
    return ok;
}
static int sameAs(const char *p, const BYTE *d, DWORD n) {
    DWORD got; char *b = readAll(p, &got); if (!b) return 0;
    int same = got == n; for (DWORD i = 0; same && i < n; i++) if ((BYTE)b[i] != d[i]) same = 0;
    HeapFree(GetProcessHeap(), 0, b);
    return same;
}
static int isOurDll(const char *p) {
    DWORD n; char *b = readAll(p, &n); if (!b) return 0;
    int ours = contains(b, n, "Controller mod loaded") || contains(b, n, "WASD mod loaded");
    HeapFree(GetProcessHeap(), 0, b);
    return ours;
}
// Marks a file as just changed: the mod reads the newest of default.txt and the
// saved layouts, so a saved layout stays in charge after an update.
static void touch(const char *p) {
    HANDLE f = CreateFileA(p, 0x100 /*FILE_WRITE_ATTRIBUTES*/, 1 | 2, 0, 3, 0x80, 0);
    if (f == (HANDLE)-1) return;
    DWORD now[2]; GetSystemTimeAsFileTime(now); SetFileTime(f, 0, 0, now);
    CloseHandle(f);
}
static int newer(const char *a, const char *b);
static void activeSettings(const char *dir, char *out);
// Files matching `name`: finds the newest; with `each`, calls it for every one.
static int findFiles(const char *dir, const char *name, char *newest, void (*each)(const char *, const char *)) {
    char pattern[PATHLEN]; join(pattern, dir, name);
    FINDDATA f; HANDLE h = FindFirstFileA(pattern, &f);
    if (h == (HANDLE)-1) return 0;
    DWORD best[2] = {0, 0}; int found = 0;
    do {
        if (f.attributes & 0x10) continue;
        char p[PATHLEN]; join(p, dir, f.name);
        if (each) each(p, f.name);
        if (!found || f.written[1] > best[1] || (f.written[1] == best[1] && f.written[0] > best[0])) {
            best[0] = f.written[0]; best[1] = f.written[1]; found = 1;
            if (newest) scpy(newest, PATHLEN, p);
        }
    } while (FindNextFileA(h, &f));
    FindClose(h);
    return found;
}
// Saved key layouts: author.txt and the editor's wasdmod-MMDDYY.txt files.
static int findLayouts(const char *dir, char *newest, void (*each)(const char *, const char *)) {
    char a[PATHLEN], b[PATHLEN];
    int hasA = findFiles(dir, "author.txt", a, each), hasB = findFiles(dir, "wasdmod*.txt", b, each);
    if (newest && (hasA || hasB)) scpy(newest, PATHLEN, hasA && (!hasB || newer(a, b)) ? a : b);
    return hasA || hasB;
}
static const char *baseName(const char *p) { const char *b = p; for (; *p; p++) if (*p == '\\' || *p == '/') b = p + 1; return b; }
static void deleteFile(const char *p, const char *name) { (void)name; DeleteFileA(p); }
// Older versions named everything wasd-mod...: a saved layout keeps its date
// (wasd-mod-093026.txt -> wasdmod-093026.txt) and its time stamp.
static char migrateDir[PATHLEN];
static void renameLegacy(const char *p, const char *name) {
    char to[PATHLEN]; join(to, migrateDir, "wasdmod"); cat(to, PATHLEN, name + 8);
    MoveFileExA(p, to, 1 /*MOVEFILE_REPLACE_EXISTING*/);
}

static int newer(const char *a, const char *b) { // a changed after b
    FILEINFO x, y;
    if (!GetFileAttributesExA(a, 0, &x)) return 0;
    if (!GetFileAttributesExA(b, 0, &y)) return 1;
    return x.written[1] > y.written[1] || (x.written[1] == y.written[1] && x.written[0] > y.written[0]);
}

static int gamePathKind(const char *p) {
    DWORD a = GetFileAttributesA(p);
    return a == 0xFFFFFFFF ? 0 : a & 0x10 ? 2 : 1;
}
#include "game_paths.inc"

static int gameRunning(void) {
    HANDLE s = CreateToolhelp32Snapshot(2 /*TH32CS_SNAPPROCESS*/, 0);
    if (s == (HANDLE)-1) return 0;
    PROCESSENTRY e; memset(&e, 0, sizeof(e)); e.size = sizeof(e);
    int found = 0;
    for (BOOL ok = Process32First(s, &e); ok && !found; ok = Process32Next(s, &e)) if (gameExecutableName(e.exe)) found = 1;
    CloseHandle(s);
    return found;
}

// ---------------------------------------------------------------- finding the game

static int tryLibrary(const char *lib, char *out) {
    const char *names[] = {"Minecraft Dungeons II", "Minecraft Dungeons 2"};
    char common[PATHLEN];
    if (!gameJoin(common, lib, "steamapps\\common")) return 0;
    for (unsigned i = 0; i < sizeof(names) / sizeof(*names); i++) {
        char root[PATHLEN];
        if (gameJoin(root, common, names[i]) && gameAt(root, out)) return 1;
    }
    return 0;
}
static int regString(HANDLE root, const char *key, const char *value, char *out, DWORD cap) {
    HANDLE k; if (RegOpenKeyExA(root, key, 0, 0x20019 /*KEY_READ*/, &k)) return 0;
    DWORD type = 0, size = cap - 1; LONG r = RegQueryValueExA(k, value, 0, &type, (BYTE *)out, &size);
    RegCloseKey(k);
    if (r || (type != 1 && type != 2)) return 0;
    out[size < cap ? size : cap - 1] = 0;
    for (char *c = out; *c; c++) if (*c == '/') *c = '\\';
    unsigned n = slen(out); while (n && out[n - 1] == '\\') out[--n] = 0;
    return out[0] != 0;
}
// Steam's library list: every "path" "D:\\SteamLibrary" entry in libraryfolders.vdf.
static int searchLibraries(const char *steam, char *out) {
    if (tryLibrary(steam, out)) return 1;
    char p[PATHLEN]; join(p, steam, "steamapps\\libraryfolders.vdf");
    DWORD n; char *b = readAll(p, &n); if (!b) return 0;
    int found = 0;
    for (DWORD i = 0; i + 6 < n && !found; i++) {
        if (b[i] != '"' || low(b[i + 1]) != 'p' || low(b[i + 2]) != 'a' || low(b[i + 3]) != 't' || low(b[i + 4]) != 'h' || b[i + 5] != '"') continue;
        DWORD j = i + 6; while (j < n && b[j] != '"' && b[j] != '\n') j++;
        if (j >= n || b[j] != '"') continue;
        char lib[PATHLEN]; unsigned k = 0; j++;
        while (j < n && b[j] != '"' && k + 1 < sizeof(lib)) {
            if (b[j] == '\\' && j + 1 < n && b[j + 1] == '\\') j++; // "D:\\SteamLibrary"
            lib[k++] = b[j] == '/' ? '\\' : b[j];
            j++;
        }
        lib[k] = 0;
        found = tryLibrary(lib, out);
    }
    HeapFree(GetProcessHeap(), 0, b);
    return found;
}
static int findGame(char *out) {
    char steam[PATHLEN];
    if (regString((HANDLE)0x80000001 /*HKCU*/, "Software\\Valve\\Steam", "SteamPath", steam, sizeof(steam)) && searchLibraries(steam, out)) return 1;
    if (regString((HANDLE)0x80000002 /*HKLM*/, "SOFTWARE\\WOW6432Node\\Valve\\Steam", "InstallPath", steam, sizeof(steam)) && searchLibraries(steam, out)) return 1;
    if (regString((HANDLE)0x80000002, "SOFTWARE\\Valve\\Steam", "InstallPath", steam, sizeof(steam)) && searchLibraries(steam, out)) return 1;
    const char *guesses[] = {"C:\\Program Files (x86)\\Steam", "C:\\Program Files\\Steam", "D:\\SteamLibrary", "D:\\Steam", "E:\\SteamLibrary"};
    for (unsigned i = 0; i < sizeof(guesses) / sizeof(*guesses); i++) if (tryLibrary(guesses[i], out)) return 1;
    // Bought from Minecraft.net (Minecraft Launcher) or the Xbox app: X:\XboxGames on
    // any local drive (removable ones are skipped: an empty card reader asks for a disk).
    DWORD drives = GetLogicalDrives();
    for (int d = 2; d < 26; d++) {
        if (!(drives >> d & 1)) continue;
        char root[4] = {(char)('A' + d), ':', '\\', 0};
        if (GetDriveTypeA(root) != 3 /*DRIVE_FIXED*/) continue;
        const char *places[] = {"XboxGames\\Minecraft Dungeons II", "XboxGames\\Minecraft Dungeons 2",
                                "Games\\Minecraft Dungeons II", "Games\\Minecraft Dungeons 2"};
        for (unsigned i = 0; i < sizeof(places) / sizeof(*places); i++) {
            char dir[PATHLEN];
            if (gameJoin(dir, root, places[i]) && gameAt(dir, out)) return 1;
        }
    }
    return 0;
}

// ---------------------------------------------------------------- install / uninstall

// Writes a built-in layout (default.txt, author.txt), which makes it the newest
// file and so the one the mod uses; an edited copy is kept as NAME.bak.
static int putLayout(const char *dir, const char *name, const BYTE *d, DWORD n) {
    char p[PATHLEN], bak[PATHLEN]; join(p, dir, name);
    if (exists(p) && !sameAs(p, d, n)) { scpy(bak, PATHLEN, p); cat(bak, PATHLEN, ".bak"); CopyFileA(p, bak, 0); }
    return writeAll(p, d, n);
}

enum { OK, ERR_RUNNING, ERR_OTHER_DLL, ERR_WRITE };
static const char *errorText[] = { // in English (the command line); the window translates them
    "",
    N_("Minecraft Dungeons II is running. Close it, then try again."),
    N_("The game folder already has a different xinput1_4.dll (another mod?)."),
    N_("Couldn't write to the game folder. Try running this installer as administrator."),
};

static int install(const char *dir, int replaceOther) {
    if (gameRunning()) return ERR_RUNNING;
    char dll[PATHLEN], ini[PATHLEN], txt[PATHLEN], editor[PATHLEN], p[PATHLEN];
    join(dll, dir, "xinput1_4.dll"); join(ini, dir, "default.txt"); join(editor, dir, "Key Layout Editor.html");
    if (exists(dll) && !isOurDll(dll)) {
        if (!replaceOther) return ERR_OTHER_DLL;
        join(p, dir, "xinput1_4.dll.other");
        if (!CopyFileA(dll, p, 0)) return ERR_WRITE;
    }
    if (!writeAll(dll, payloadDll, sizeof(payloadDll))) return ERR_WRITE;
    join(p, dir, "xinput1_4.dll.off"); if (exists(p) && isOurDll(p)) DeleteFileA(p); // installing turns it back on
    scpy(migrateDir, PATHLEN, dir); findFiles(dir, "wasd-mod*.txt", 0, renameLegacy);
    // The settings file used to be wasd-mod.ini, then wasdmod.ini; edited ones are kept as default.txt.bak.
    const char *oldIni[] = {"wasd-mod.ini", "wasdmod.ini"};
    for (unsigned i = 0; i < 2; i++) {
        join(p, dir, oldIni[i]);
        if (exists(p)) { char bak[PATHLEN]; join(bak, dir, "default.txt.bak"); if (!sameAs(p, payloadIni, sizeof(payloadIni))) CopyFileA(p, bak, 0); DeleteFileA(p); }
    }
    join(p, dir, "wasd-mod.log"); DeleteFileA(p);
    activeSettings(dir, txt); // the layout in use before the update
    if (!putLayout(dir, "default.txt", payloadIni, sizeof(payloadIni))) return ERR_WRITE;
    writeAll(editor, payloadEditor, sizeof(payloadEditor));
    // It stays in use: a saved layout is marked newer than the fresh default.txt. (Not
    // the newest saved one: a player who picked Default stays on Default.)
    if (!sameText(baseName(txt), "default.txt") && exists(txt)) touch(txt);
    return OK;
}

static int uninstall(const char *dir, int removeLayout) {
    if (gameRunning()) return ERR_RUNNING;
    char p[PATHLEN];
    join(p, dir, "xinput1_4.dll"); if (exists(p) && isOurDll(p) && !DeleteFileA(p)) return ERR_WRITE;
    join(p, dir, "xinput1_4.dll.off"); if (exists(p) && isOurDll(p)) DeleteFileA(p);
    const char *files[] = {"default.txt", "default.txt.bak", "wasdmod.log", "wasdmod.old.log", "wasdmod-record.flag", "Key Layout Editor.html", "wasdmod.ini", "wasdmod.ini.bak", "wasd-mod.ini", "wasd-mod.ini.bak", "wasd-mod.log"};
    for (unsigned i = 0; i < sizeof(files) / sizeof(*files); i++) { join(p, dir, files[i]); DeleteFileA(p); }
    if (removeLayout) { findLayouts(dir, 0, deleteFile); findFiles(dir, "wasd-mod*.txt", 0, deleteFile); join(p, dir, "author.txt.bak"); DeleteFileA(p); }
    return OK;
}

enum { NOT_INSTALLED, INSTALLED_LATEST, INSTALLED_OLDER, OTHER_DLL, TURNED_OFF };
static int installState(const char *dir) {
    char dll[PATHLEN], off[PATHLEN]; join(dll, dir, "xinput1_4.dll"); join(off, dir, "xinput1_4.dll.off");
    if (!exists(dll)) return exists(off) && isOurDll(off) ? TURNED_OFF : NOT_INSTALLED;
    if (!isOurDll(dll)) return OTHER_DLL;
    return sameAs(dll, payloadDll, sizeof(payloadDll)) ? INSTALLED_LATEST : INSTALLED_OLDER;
}
// The settings file the mod uses: the newest saved layout when it's newer than default.txt.
static void activeSettings(const char *dir, char *out) {
    char ini[PATHLEN], txt[PATHLEN]; join(ini, dir, "default.txt");
    scpy(out, PATHLEN, findLayouts(dir, txt, 0) && newer(txt, ini) ? txt : ini);
}
// Turning the mod off renames it to xinput1_4.dll.off: the game starts without it
// and loads the system's XInput, and the settings and layouts stay for next time.
// Works with the game running too (it applies the next time the game starts).
static int turnOn(const char *dir, int on) {
    char dll[PATHLEN], off[PATHLEN]; join(dll, dir, "xinput1_4.dll"); join(off, dir, "xinput1_4.dll.off");
    if (on) return exists(dll) ? OK : isOurDll(off) && MoveFileExA(off, dll, 0) ? OK : ERR_WRITE;
    if (!exists(dll) || !isOurDll(dll)) return OK;
    return MoveFileExA(dll, off, 1 /*MOVEFILE_REPLACE_EXISTING*/) ? OK : ERR_WRITE;
}
// Switches the layout: 0 Default, 1 Recommended, 2 your newest wasdmod*.txt.
static int useLayout(const char *dir, int which) {
    char p[PATHLEN];
    if (which == 0) return putLayout(dir, "default.txt", payloadIni, sizeof(payloadIni)) ? OK : ERR_WRITE;
    if (which == 1) return putLayout(dir, "author.txt", payloadAuthor, sizeof(payloadAuthor)) ? OK : ERR_WRITE;
    if (!findFiles(dir, "wasdmod*.txt", p, 0)) return ERR_WRITE;
    touch(p);
    return OK;
}

// ---------------------------------------------------------------- window

enum { ID_PATH = 10, ID_BROWSE, ID_INSTALL, ID_UNINSTALL, ID_EDITOR, ID_LOAD, ID_SETTINGS, ID_STATUS, ID_DEFAULT, ID_RECOMMENDED, ID_OWN, ID_ONOFF, ID_RECORD };
static HANDLE onOffBtn, recordBtn;
static HANDLE mainWnd, fontNormal, fontTitle, fontSmall, statusWnd, pathWnd, installBtn, uninstallBtn, editorBtn, loadBtn, settingsBtn, layoutBtn[3];
static HANDLE titleWnd, introWnd, folderLabel, browseBtn, layoutLabel, recordHint, footerWnd, fontStrong, fontStatus, fontKey;
static char gameDir[PATHLEN];
static int dpi = 96;
static int S(int v) { return v * dpi / 96; }
static const char *TITLE = "wasdmod";

// ---------------------------------------------------------------- key layout editor
//
// "Edit key layout" serves the editor on 127.0.0.1 (a free port, with a random
// token in every path so no other page can use it) and opens it as an app window
// (Edge or Chrome --app, otherwise the default browser). window.wasdmodHost in the
// page keeps its layouts in %APPDATA%\wasdmod\editor.json and saves straight into
// the game folder, while this window stays open.
#define WM_EDITOR_SAVED 0x8001 // WM_APP + 1
#define WM_LANGUAGE 0x8002     // WM_APP + 2: a language was picked in the editor
#define MAXREQ (2 << 20)
static WORD serverPort;
static char token[33], savedName[PATHLEN];

static void num10(unsigned v, char *out) { char t[12]; int n = 0; do t[n++] = (char)('0' + v % 10); while (v /= 10); int i = 0; while (n) out[i++] = t[--n]; out[i] = 0; }
static void storePath(char *out) {
    char dir[PATHLEN] = ""; out[0] = 0;
    if (!GetEnvironmentVariableA("APPDATA", dir, 300)) return;
    cat(dir, PATHLEN, "\\wasdmod"); CreateDirectoryA(dir, 0);
    join(out, dir, "editor.json");
}
static void sendAll(SOCKET s, const char *d, DWORD n) {
    while (n) { int k = send(s, d, n > 65536 ? 65536 : (int)n, 0); if (k <= 0) return; d += k; n -= (DWORD)k; }
}
static void reply(SOCKET s, const char *status, const char *type, const char *body, DWORD n) {
    char head[300] = "HTTP/1.1 ", num[12];
    cat(head, sizeof(head), status); cat(head, sizeof(head), "\r\nContent-Type: "); cat(head, sizeof(head), type);
    cat(head, sizeof(head), "\r\nCache-Control: no-store\r\nConnection: close\r\nContent-Length: ");
    num10(n, num); cat(head, sizeof(head), num); cat(head, sizeof(head), "\r\n\r\n");
    sendAll(s, head, slen(head)); sendAll(s, body, n);
}
static void replyText(SOCKET s, const char *status, const char *text) { reply(s, status, "text/plain; charset=utf-8", text, slen(text)); }

// The editor with window.wasdmodHost, after the page's first four lines (doctype,
// html, and the two meta tags build.sh puts there).
static const char *HOST_A = "<script type=\"application/json\" id=\"wasdmod-store\">";
static const char *HOST_B =
    "</script>\n<script>\n"
    "window.wasdmodHost = (() => {\n"
    "  let store = {}, chain = Promise.resolve();\n"
    "  try { store = JSON.parse(document.getElementById(\"wasdmod-store\").textContent) || {}; } catch (e) {}\n"
    "  const base = \"/";
static const char *HOST_C = "/\";\n"
    "  const send = (path, body) => fetch(base + path, { method: \"POST\", body });\n"
    "  return {\n"
    "    store,\n"
    "    lang: \"";
static const char *HOST_D = "\",\n"
    "    app: \"win\",\n"
    "    game: ";
static const char *HOST_E = ",\n"
    "    set(k, v) { store[k] = v; const body = JSON.stringify(store).replace(/</g, \"\\\\u003c\"); chain = chain.then(() => send(\"store\", body)).catch(() => {}); },\n"
    "    async gameControls() { const r = await send(\"controls\", \"\"); const t = await r.text(); return r.ok && t ? t : null; },\n"
    "    async writeGameControls(data) { const r = await send(\"controls-write\", data); const t = await r.text(); if (!r.ok) throw new Error(t); return t; },\n"
    "    setLang(code) { chain = chain.then(() => send(\"lang?\" + encodeURIComponent(code), \"\")).catch(() => {}); },\n"
    "    async save(name, text) { const r = await send(\"save?name=\" + encodeURIComponent(name), text); const t = await r.text(); if (!r.ok) throw new Error(t); return t; }\n"
    "  };\n"
    "})();\n"
    "</script>\n";
// Text as a JSON string; < as \u003c so it can't end the script.
static char *jsonString(char *o, const char *t, DWORD n) {
    *o++ = '"';
    for (DWORD i = 0; i < n; i++) {
        BYTE c = (BYTE)t[i];
        if (c == '"' || c == '\\') { *o++ = '\\'; *o++ = (char)c; }
        else if (c < 0x20 || c == '<') { memcpy(o, "\\u00", 4); o += 4; *o++ = "0123456789abcdef"[c >> 4]; *o++ = "0123456789abcdef"[c & 15]; }
        else *o++ = (char)c;
    }
    *o++ = '"';
    return o;
}
static void servePage(SOCKET s) {
    char path[PATHLEN]; DWORD storeN = 0; char *saved = 0;
    // The layout the game uses, so the editor can show it (and add it when it's not there).
    char active[PATHLEN] = ""; DWORD gameN = 0; char *gameText = 0;
    if (gameDir[0] && installState(gameDir) != NOT_INSTALLED) { activeSettings(gameDir, active); if (active[0]) gameText = readAll(active, &gameN); }
    const char *gameName = baseName(active);
    storePath(path); if (path[0]) saved = readAll(path, &storeN);
    if (saved && (storeN == 0 || saved[0] != '{' || contains(saved, storeN, "</"))) { HeapFree(GetProcessHeap(), 0, saved); saved = 0; }
    DWORD off = 0, size = sizeof(payloadEditor);
    for (int lines = 0; off < size && lines < 4; off++) if (payloadEditor[off] == '\n') lines++;
    const char *code = LANG_CODE[langIndex];
    DWORD a = slen(HOST_A), b = slen(HOST_B), c = slen(HOST_C), d = slen(HOST_D), lc = slen(code), st = saved ? storeN : 2;
    DWORD e = slen(HOST_E), gn = gameText ? 24 + 6 * (slen(gameName) + gameN) : 4;
    DWORD total = off + a + st + b + 32 + c + lc + d + gn + e + (size - off);
    char *page = HeapAlloc(GetProcessHeap(), 0, total), *o = page;
    if (!page) { replyText(s, "500 Internal Server Error", "Out of memory."); if (saved) HeapFree(GetProcessHeap(), 0, saved); if (gameText) HeapFree(GetProcessHeap(), 0, gameText); return; }
    memcpy(o, payloadEditor, off); o += off;
    memcpy(o, HOST_A, a); o += a;
    memcpy(o, saved ? saved : "{}", st); o += st;
    memcpy(o, HOST_B, b); o += b;
    memcpy(o, token, 32); o += 32;
    memcpy(o, HOST_C, c); o += c;
    memcpy(o, code, lc); o += lc;
    memcpy(o, HOST_D, d); o += d;
    if (gameText) {
        memcpy(o, "{\"file\":", 8); o += 8; o = jsonString(o, gameName, slen(gameName));
        memcpy(o, ",\"text\":", 8); o += 8; o = jsonString(o, gameText, gameN); *o++ = '}';
    } else { memcpy(o, "null", 4); o += 4; }
    memcpy(o, HOST_E, e); o += e;
    memcpy(o, payloadEditor + off, size - off); o += size - off;
    reply(s, "200 OK", "text/html; charset=utf-8", page, (DWORD)(o - page));
    HeapFree(GetProcessHeap(), 0, page);
    if (saved) HeapFree(GetProcessHeap(), 0, saved);
    if (gameText) HeapFree(GetProcessHeap(), 0, gameText);
}
static int hexVal(char c) { return c >= '0' && c <= '9' ? c - '0' : low(c) >= 'a' && low(c) <= 'f' ? low(c) - 'a' + 10 : -1; }
static void serveSave(SOCKET s, const char *query, const char *body, DWORD n) {
    char name[80]; unsigned k = 0;
    if (sameTextN(query, "name=", 5)) for (const char *q = query + 5; *q && *q != '&' && k + 1 < sizeof(name); q++) {
        if (*q == '%' && hexVal(q[1]) >= 0 && hexVal(q[2]) >= 0) { name[k++] = (char)(hexVal(q[1]) * 16 + hexVal(q[2])); q += 2; }
        else name[k++] = *q == '+' ? ' ' : *q;
    }
    name[k] = 0;
    // Only the editor's names (default.txt, author.txt, wasdmod-MMDDYY.txt); anything else is wasdmod.txt.
    int safe = 1; for (unsigned i = 0; i < k; i++) if (name[i] == '\\' || name[i] == '/' || name[i] == ':' || (BYTE)name[i] < 32) safe = 0;
    int keep = safe && ((k > 11 && sameTextN(name, "wasdmod", 7) && sameText(name + k - 4, ".txt")) || sameText(name, "author.txt") || sameText(name, "default.txt"));
    if (!keep) scpy(name, sizeof(name), "wasdmod.txt");
    if (!gameDir[0] || !isGameDir(gameDir)) return replyText(s, "409 Conflict", T("The game folder wasn't found. Pick it in the setup window."));
    if (!contains(body, n, "[Buttons]") && !contains(body, n, "[Move]")) return replyText(s, "400 Bad Request", T("That isn't a key layout."));
    if (!putLayout(gameDir, name, (const BYTE *)body, n)) return replyText(s, "500 Internal Server Error", T(errorText[ERR_WRITE]));
    scpy(savedName, sizeof(savedName), name);
    if (mainWnd) PostMessageA(mainWnd, WM_EDITOR_SAVED, 0, 0);
    // Saved but not in use yet: "saved:" tells the editor it isn't an error.
    int state = installState(gameDir);
    char why[600] = "saved:";
    if (state == TURNED_OFF) { cat(why, sizeof(why), T("Saved, but wasdmod is turned off: click Turn on in the setup window.")); return replyText(s, "409 Conflict", why); }
    if (state != INSTALLED_LATEST && state != INSTALLED_OLDER) { cat(why, sizeof(why), T("Saved, but the mod isn't installed yet: click Install in the setup window.")); return replyText(s, "409 Conflict", why); }
    char active[PATHLEN]; activeSettings(gameDir, active);
    replyText(s, "200 OK", baseName(active));
}
// The game's own keyboard settings (Settings > Controls > Keyboard), which the editor
// reads to show the game's real keys and can write while the game is closed (the
// first write keeps the original as .wasdmod-backup). Sent as base64.
static int controlsPath(char *out) {
    char base[PATHLEN] = "";
    if (!GetEnvironmentVariableA("LOCALAPPDATA", base, 400)) return 0;
    join(out, base, "Dungeons2\\Saved\\SaveGames\\EnhancedInputUserSettings.sav");
    return exists(out);
}
static const char B64[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void serveControls(SOCKET s) {
    char p[PATHLEN]; DWORD n = 0; char *d = controlsPath(p) ? readAll(p, &n) : 0;
    if (!d) { replyText(s, "200 OK", ""); return; }
    DWORD m = (n + 2) / 3 * 4; char *o = HeapAlloc(GetProcessHeap(), 0, m + 1);
    if (o) {
        for (DWORD i = 0, k = 0; i < n; i += 3) {
            DWORD v = (BYTE)d[i] << 16 | (i + 1 < n ? (BYTE)d[i + 1] << 8 : 0) | (i + 2 < n ? (BYTE)d[i + 2] : 0);
            o[k++] = B64[v >> 18 & 63]; o[k++] = B64[v >> 12 & 63];
            o[k++] = i + 1 < n ? B64[v >> 6 & 63] : '='; o[k++] = i + 2 < n ? B64[v & 63] : '=';
        }
        reply(s, "200 OK", "text/plain", o, m); HeapFree(GetProcessHeap(), 0, o);
    } else replyText(s, "500 Internal Server Error", "Out of memory.");
    HeapFree(GetProcessHeap(), 0, d);
}
static void serveControlsWrite(SOCKET s, const char *body, DWORD n) {
    char p[PATHLEN], backup[PATHLEN + 20];
    if (!controlsPath(p)) { replyText(s, "500 Internal Server Error", T("The game's controls file wasn't found. Change any key in the game's settings once, then try again.")); return; }
    if (gameRunning()) { replyText(s, "500 Internal Server Error", T(errorText[ERR_RUNNING])); return; }
    BYTE *d = HeapAlloc(GetProcessHeap(), 0, n / 4 * 3 + 3); DWORD k = 0, v = 0; int bits = 0;
    if (!d) { replyText(s, "500 Internal Server Error", "Out of memory."); return; }
    for (DWORD i = 0; i < n && body[i] != '='; i++) {
        const char *c = B64; while (*c && *c != body[i]) c++;
        if (!*c) continue;
        v = v << 6 | (DWORD)(c - B64); bits += 6;
        if (bits >= 8) { bits -= 8; d[k++] = (BYTE)(v >> bits); }
    }
    scpy(backup, sizeof(backup), p); cat(backup, sizeof(backup), ".wasdmod-backup");
    if (k < 8 || d[0] != 'G' || d[1] != 'V' || d[2] != 'A' || d[3] != 'S') replyText(s, "500 Internal Server Error", "Not a settings file.");
    else if (!exists(backup) && !CopyFileA(p, backup, 1)) replyText(s, "500 Internal Server Error", T("Couldn't write the game's controls file."));
    else if (!writeAll(p, d, k)) replyText(s, "500 Internal Server Error", T("Couldn't write the game's controls file."));
    else replyText(s, "200 OK", "ok");
    HeapFree(GetProcessHeap(), 0, d);
}
static DWORD serveOne(void *arg) {
    SOCKET s = (SOCKET)arg;
    DWORD timeout = 15000; setsockopt(s, 0xFFFF /*SOL_SOCKET*/, 0x1006 /*SO_RCVTIMEO*/, (const char *)&timeout, 4);
    char *buf = HeapAlloc(GetProcessHeap(), 0, MAXREQ + 1);
    DWORD got = 0, headEnd = 0, want = 0;
    while (buf && got < MAXREQ) {
        int k = recv(s, buf + got, MAXREQ - got, 0); if (k <= 0) break;
        got += (DWORD)k;
        if (!headEnd) for (DWORD i = 0; i + 3 < got; i++) if (buf[i] == '\r' && buf[i + 1] == '\n' && buf[i + 2] == '\r' && buf[i + 3] == '\n') {
            headEnd = i + 4; want = headEnd;
            for (DWORD j = 0; j + 16 < headEnd; j++) if (sameTextN(buf + j, "\ncontent-length:", 16)) {
                DWORD v = 0; for (DWORD m = j + 16; m < headEnd && (buf[m] == ' ' || (buf[m] >= '0' && buf[m] <= '9')); m++) if (buf[m] != ' ') v = v * 10 + (DWORD)(buf[m] - '0');
                want = headEnd + (v < MAXREQ ? v : MAXREQ);
            }
            break;
        }
        if (headEnd && got >= want) break;
    }
    if (buf && headEnd) {
        buf[got] = 0;
        // "GET /<token>/ HTTP/1.1", "POST /<token>/store", "POST /<token>/save?name=..."
        int post = sameTextN(buf, "POST /", 6), get = sameTextN(buf, "GET /", 5);
        char *path = buf + (post ? 6 : 5), *rest = path + 33;
        int ours = (post || get) && headEnd > 45 && sameTextN(path, token, 32) && path[32] == '/';
        char *body = buf + headEnd; DWORD n = got - headEnd;
        if (ours && get && rest[0] == ' ') servePage(s);
        else if (ours && post && sameTextN(rest, "store ", 6)) {
            char p[PATHLEN]; storePath(p);
            if (n && body[0] == '{' && p[0] && writeAll(p, body, n)) replyText(s, "200 OK", "");
            else replyText(s, "500 Internal Server Error", "Couldn't keep the layouts.");
        } else if (ours && post && sameTextN(rest, "lang?", 5)) {
            char code[16] = {0}; unsigned k = 0;
            for (const char *q = rest + 5; *q && *q != ' ' && k + 1 < sizeof(code); q++) code[k++] = *q;
            int l = langOf(code);
            if (l >= 0) { langIndex = l; if (mainWnd) PostMessageA(mainWnd, WM_LANGUAGE, 0, 0); }
            replyText(s, "200 OK", "");
        } else if (ours && post && sameTextN(rest, "controls ", 9)) serveControls(s);
        else if (ours && post && sameTextN(rest, "controls-write ", 15)) serveControlsWrite(s, body, n);
        else if (ours && post && sameTextN(rest, "save?", 5)) {
            char *q = rest + 5; char *e = q; while (*e && *e != ' ') e++;
            *e = 0; serveSave(s, q, body, n);
        } else replyText(s, "404 Not Found", "Not found.");
    }
    if (buf) HeapFree(GetProcessHeap(), 0, buf);
    closesocket(s);
    return 0;
}
static DWORD acceptLoop(void *arg) {
    for (;;) {
        SOCKET s = accept((SOCKET)arg, 0, 0);
        if (s == (SOCKET)-1) { Sleep(100); continue; }
        HANDLE t = CreateThread(0, 0, serveOne, (void *)s, 0, 0); // one thread each: browsers keep idle connections open
        if (t) CloseHandle(t); else closesocket(s);
    }
}
static int startServer(void) {
    if (serverPort) return 1;
    BYTE wsa[512], r[16];
    if (WSAStartup(0x0202, wsa) || !SystemFunction036(r, 16)) return 0;
    for (int i = 0; i < 16; i++) { token[2 * i] = "0123456789abcdef"[r[i] >> 4]; token[2 * i + 1] = "0123456789abcdef"[r[i] & 15]; }
    token[32] = 0;
    SOCKET l = socket(2 /*AF_INET*/, 1 /*SOCK_STREAM*/, 6 /*TCP*/);
    if (l == (SOCKET)-1) return 0;
    SOCKADDR_IN a; memset(&a, 0, sizeof(a)); a.family = 2; a.addr = 0x0100007F; // 127.0.0.1, port 0: any free one
    int len = sizeof(a);
    if (bind(l, &a, sizeof(a)) || listen(l, 16) || getsockname(l, &a, &len)) { closesocket(l); return 0; }
    HANDLE t = CreateThread(0, 0, acceptLoop, (void *)l, 0, 0);
    if (!t) { closesocket(l); return 0; }
    CloseHandle(t);
    serverPort = (WORD)((a.port >> 8) | (a.port << 8));
    return 1;
}
static void editorUrl(char *url) {
    char num[8]; scpy(url, 120, "http://127.0.0.1:"); num10(serverPort, num);
    cat(url, 120, num); cat(url, 120, "/"); cat(url, 120, token); cat(url, 120, "/");
}
// Edge (on every Windows 10/11 PC) or Chrome, whose --app mode is a plain window.
static int findAppBrowser(char *out) {
    const char *keys[] = {"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\App Paths\\msedge.exe", "SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\App Paths\\chrome.exe"};
    for (unsigned i = 0; i < 2; i++) for (unsigned root = 0; root < 2; root++) {
        if (!regString((HANDLE)(U64)(root ? 0x80000001 : 0x80000002), keys[i], "", out, PATHLEN)) continue;
        if (out[0] == '"') { unsigned n = slen(out); scpy(out, PATHLEN, out + 1); if (n > 1 && out[n - 2] == '"') out[n - 2] = 0; }
        if (exists(out)) return 1;
    }
    const char *guesses[] = {"C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe", "C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe"};
    for (unsigned i = 0; i < 2; i++) if (exists(guesses[i])) { scpy(out, PATHLEN, guesses[i]); return 1; }
    return 0;
}
// ---------------------------------------------------------------- Record Logs
//
// While wasdmod-record.flag is in the game folder, the mod logs each key and mouse
// button it handles. Stop and save logs writes one text file to the Desktop for a
// bug report: the system, the mod's state, the layout in use and the log.
static int recordingOn(const char *dir) { char p[PATHLEN]; join(p, dir, "wasdmod-record.flag"); return exists(p); }
static int setRecording(const char *dir, int on) {
    char p[PATHLEN]; join(p, dir, "wasdmod-record.flag");
    if (!on) { DeleteFileA(p); return OK; }
    return writeAll(p, "", 0) ? OK : ERR_WRITE;
}
typedef struct { char *b; DWORD n, cap; } TEXT;
static void put(TEXT *t, const char *s, DWORD n) { while (n-- && t->n + 1 < t->cap) t->b[t->n++] = *s++; t->b[t->n] = 0; }
static void puts_(TEXT *t, const char *s) { put(t, s, slen(s)); }
static void putNum(TEXT *t, unsigned v) { char b[12]; num10(v, b); puts_(t, b); }
// The end of a file: at most `keep` bytes, starting at a line; with `settingsOnly`,
// without the comment lines (a layout's explanations).
static void putTail(TEXT *t, const char *path, DWORD keep, int settingsOnly) {
    DWORD n; char *b = readAll(path, &n); if (!b) return;
    DWORD from = n > keep ? n - keep : 0;
    if (from) while (from < n && b[from - 1] != '\n') from++;
    int skip = 0;
    for (DWORD i = from; i < n; i++) {
        if (i == from || b[i - 1] == '\n') skip = settingsOnly && (b[i] == ';' || b[i] == '\r' || b[i] == '\n');
        if (!skip && b[i] != '\r') put(t, b + i, 1);
    }
    HeapFree(GetProcessHeap(), 0, b);
}
static int writeReport(const char *dir, char *out) {
    char desk[PATHLEN] = "", p[PATHLEN], active[PATHLEN], name[64] = "wasdmod-logs-";
    if (SHGetFolderPathA(0, 0x10 /*CSIDL_DESKTOPDIRECTORY*/, 0, 0, desk) != 0 && !GetEnvironmentVariableA("USERPROFILE", desk, 300)) return ERR_WRITE;
    SYSTEMTIME t; GetLocalTime(&t);
    char d[16]; num10(t.year, d); cat(name, sizeof(name), d);
    char two[3] = {0, 0, 0};
    WORD parts[4] = {t.month, t.day, t.hour, t.minute};
    for (int i = 0; i < 4; i++) { if (i == 2) cat(name, sizeof(name), "-"); two[0] = (char)('0' + parts[i] / 10); two[1] = (char)('0' + parts[i] % 10); cat(name, sizeof(name), two); }
    cat(name, sizeof(name), ".txt");
    join(out, desk, name);
    TEXT r; r.cap = 2u << 20; r.n = 0; r.b = HeapAlloc(GetProcessHeap(), 0, r.cap); if (!r.b) return ERR_WRITE; r.b[0] = 0;
    puts_(&r, "wasdmod logs, "); putNum(&r, t.year); puts_(&r, "-"); put(&r, name + 17, 2); puts_(&r, "-"); put(&r, name + 19, 2);
    puts_(&r, " "); put(&r, name + 22, 2); puts_(&r, ":"); put(&r, name + 24, 2); puts_(&r, "\n");
    puts_(&r, "App: wasdmod setup for Windows " VERSION "\n");
    HANDLE nt = GetModuleHandleA("ntdll.dll");
    const char *(*wine)(void) = nt ? GetProcAddress(nt, "wine_get_version") : 0;
    typedef struct { DWORD size, major, minor, build, platform; WORD csd[128]; } OSVER;
    LONG (*rtlVer)(OSVER *) = nt ? GetProcAddress(nt, "RtlGetVersion") : 0;
    OSVER v; memset(&v, 0, sizeof(v)); v.size = sizeof(v);
    puts_(&r, "System: Windows ");
    if (rtlVer && !rtlVer(&v)) { putNum(&r, v.major); puts_(&r, "."); putNum(&r, v.minor); puts_(&r, "."); putNum(&r, v.build); }
    if (wine) { puts_(&r, " (Wine "); puts_(&r, wine()); puts_(&r, ")"); }
    puts_(&r, "\nGame folder: ");
    char home[PATHLEN] = ""; unsigned hl = GetEnvironmentVariableA("USERPROFILE", home, 300) ? slen(home) : 0;
    if (hl && sameTextN(dir, home, hl)) { puts_(&r, "%USERPROFILE%"); puts_(&r, dir + hl); } else puts_(&r, dir); // no user name in the report
    const char *states[] = {"not installed", "installed, up to date", "installed, older version", "a different xinput1_4.dll", "turned off"};
    puts_(&r, "\nMod: "); puts_(&r, states[installState(dir)]);
    activeSettings(dir, active);
    puts_(&r, "\nLayout in use: "); puts_(&r, exists(active) ? baseName(active) : "none"); puts_(&r, "\n");
    if (exists(active)) { puts_(&r, "\n===== "); puts_(&r, baseName(active)); puts_(&r, " =====\n"); putTail(&r, active, 64 << 10, 1); }
    join(p, dir, "wasdmod.old.log");
    if (exists(p)) { puts_(&r, "\n===== wasdmod.old.log (end) =====\n"); putTail(&r, p, 32 << 10, 0); }
    puts_(&r, "\n===== wasdmod.log =====\n");
    join(p, dir, "wasdmod.log");
    if (exists(p)) putTail(&r, p, 1200 << 10, 0); else puts_(&r, "(no log yet: start the game once with wasdmod installed)\n");
    int ok = writeAll(out, r.b, r.n);
    HeapFree(GetProcessHeap(), 0, r.b);
    return ok ? OK : ERR_WRITE;
}

// Without WebView2: the editor as an Edge or Chrome app window, else in the browser.
static void openEditorInBrowser(void) {
    char url[120], exe[PATHLEN], args[220] = "--app=";
    editorUrl(url);
    if (findAppBrowser(exe)) { cat(args, sizeof(args), url); cat(args, sizeof(args), " --window-size=1200,860"); ShellExecuteA(mainWnd, "open", exe, args, 0, 1); }
    else ShellExecuteA(mainWnd, "open", url, 0, 0, 1);
}
static int openEditorWindow(void);
static int openEditor(void) {
    if (!startServer()) return 0;
    if (!openEditorWindow()) openEditorInBrowser();
    return 1;
}

// Text for the window: translated text is UTF-8, paths are in the ANSI code page.
static WCHAR *W(const char *s) { // a few at a time (a message box needs two)
    static WCHAR buf[4][2048]; static int next;
    WCHAR *w = buf[next++ & 3];
    if (!MultiByteToWideChar(65001 /*CP_UTF8*/, 0, s, -1, w, 2048)) w[0] = 0;
    return w;
}
static void setText(HANDLE c, const char *s) { SetWindowTextW(c, W(s)); }
static void setPath(HANDLE c, const char *p) { WCHAR w[PATHLEN]; if (!MultiByteToWideChar(0 /*CP_ACP*/, 0, p, -1, w, PATHLEN)) w[0] = 0; SetWindowTextW(c, w); }
static int ask(const char *text, UINT flags) { return MessageBoxW(mainWnd, W(text), W(TITLE), flags); }
// "Saved {file} ..." with {file} filled in.
static void fill(char *out, unsigned cap, const char *text, const char *value) {
    out[0] = 0;
    for (const char *p = text; *p; ) {
        if (sameTextN(p, "{file}", 6)) { cat(out, cap, value); p += 6; continue; }
        char c[2] = {*p++, 0}; cat(out, cap, c);
    }
}

// ---------------------------------------------------------------- look
//
// The look of the website and the key layout editor: near-black, warm light behind
// the gamepad, dark cards with a hairline edge, Apple blue for the thing to do, the
// state's colour glowing in the status card, and keys drawn as little keycaps.
// Whatever doesn't change on hover is painted once, into `canvas` (layout() does
// it); the labels and buttons take their background from it (a pattern brush), so
// they sit on the light seamlessly. GDI+ draws the round shapes and the light, so
// Windows 10 looks the same as 11.
typedef DWORD COLORREF;
typedef struct { LONG x, y; } PT;
typedef struct { LONG cx, cy; } SZ;
typedef struct { REAL x, y; } PTF;
typedef struct { REAL x, y, w, h; } RECTF;
static struct { COLORREF bg, text, text2, textOff, accent, accentHi, accentDown, ok, warn, off, dot; } C;
static int dark, installAccent, radioOn[3], statusKind, recording, titlePixel; // statusKind: 0 info, 1 ok, 2 warning, 3 off
static HANDLE bgBrush, canvasBmp, canvasBrush, hovered, primaryBtn; // primaryBtn: the blue one, if any
static int canvasW, canvasH;
static WNDPROC buttonProc;
static RECT cards[4], dividers[6], statusIcon, statusRow, primaryPill, gamepad, sectionDot, hairline;
static int cardCount, dividerCount;
#define RGB(r, g, b) ((COLORREF)((r) | ((g) << 8) | ((b) << 16)))
#define ARGB(a, r, g, b) ((DWORD)(a) << 24 | (DWORD)(r) << 16 | (DWORD)(g) << 8 | (DWORD)(b))
#define FOCUS_ROOM S(3) // around each button, for its focus ring
static DWORD argb(COLORREF c, int alpha) { return (DWORD)alpha << 24 | (c & 0xFF) << 16 | (c & 0xFF00) | ((c >> 16) & 0xFF); }
static COLORREF mix(COLORREF a, COLORREF b, int pctA) { // a over b
    COLORREF out = 0;
    for (int sh = 0; sh < 24; sh += 8) out |= ((((a >> sh) & 0xFF) * pctA + ((b >> sh) & 0xFF) * (100 - pctA)) / 100) << sh;
    return out;
}
static int max2(int a, int b) { return a > b ? a : b; }
// Always dark, in the colours of the key layout editor and the website.
static void loadTheme(void) {
    dark = 1;
    C.bg = RGB(11, 11, 13); C.text = RGB(245, 245, 247); C.text2 = RGB(161, 161, 166); C.textOff = RGB(104, 104, 109);
    C.accent = RGB(10, 132, 255); C.accentHi = RGB(51, 149, 255); C.accentDown = RGB(0, 113, 227);
    C.ok = RGB(48, 209, 88); C.warn = RGB(255, 159, 10); C.off = RGB(142, 142, 147); C.dot = RGB(255, 159, 10);
    if (bgBrush) DeleteObject(bgBrush);
    bgBrush = CreateSolidBrush(C.bg);
}
// The title bar in the same colours (dark title bar; on Windows 11 the window's own colour).
static void themeWindow(HANDLE w) {
    BOOL on = dark; COLORREF bar = C.bg;
    DwmSetWindowAttribute(w, 20 /*DWMWA_USE_IMMERSIVE_DARK_MODE*/, &on, 4);
    DwmSetWindowAttribute(w, 19 /*the same, before Windows 10 20H1*/, &on, 4);
    DwmSetWindowAttribute(w, 35 /*DWMWA_CAPTION_COLOR*/, &bar, 4);
}
static HANDLE editorWnd; // the key layout editor window (below)
static void themeTitleBar(void) { themeWindow(mainWnd); if (editorWnd) themeWindow(editorWnd); }
static COLORREF statusTone(void) { return statusKind == 1 ? C.ok : statusKind == 2 ? C.warn : statusKind == 3 ? C.off : C.accent; }

// ---- GDI+ shapes and light
static void *gfx(HANDLE dc) {
    void *g = 0; GdipCreateFromHDC(dc, &g);
    if (g) { GdipSetSmoothingMode(g, 4 /*antialias*/); GdipSetPixelOffsetMode(g, 4 /*half: whole numbers fall on pixel edges*/); }
    return g;
}
static void roundPath(void *path, REAL x, REAL y, REAL w, REAL h, REAL r) {
    if (r > w / 2) r = w / 2;
    if (r > h / 2) r = h / 2;
    REAL d = 2 * r;
    GdipAddPathArc(path, x, y, d, d, 180, 90); GdipAddPathArc(path, x + w - d, y, d, d, 270, 90);
    GdipAddPathArc(path, x + w - d, y + h - d, d, d, 0, 90); GdipAddPathArc(path, x, y + h - d, d, d, 90, 90);
    GdipClosePathFigure(path);
}
static void *newRound(REAL x, REAL y, REAL w, REAL h, REAL r) { void *p = 0; GdipCreatePath(0, &p); roundPath(p, x, y, w, h, r); return p; }
static void fillRound(void *g, REAL x, REAL y, REAL w, REAL h, REAL r, DWORD c) {
    void *p = newRound(x, y, w, h, r), *b = 0;
    GdipCreateSolidFill(c, &b); GdipFillPath(g, b, p);
    GdipDeleteBrush(b); GdipDeletePath(p);
}
// A line `width` wide along the inside of the shape's edge.
static void strokeRound(void *g, REAL x, REAL y, REAL w, REAL h, REAL r, DWORD c, REAL width) {
    REAL k = width / 2; void *p = newRound(x + k, y + k, w - width, h - width, r - k), *pen = 0;
    GdipCreatePen1(c, width, 2 /*pixels*/, &pen); GdipDrawPath(g, pen, p);
    GdipDeletePen(pen); GdipDeletePath(p);
}
static void fillCircle(void *g, REAL cx, REAL cy, REAL d, DWORD c) {
    void *b = 0; GdipCreateSolidFill(c, &b); GdipFillEllipse(g, b, cx - d / 2, cy - d / 2, d, d); GdipDeleteBrush(b);
}
static void ringCircle(void *g, REAL cx, REAL cy, REAL d, DWORD c, REAL width) {
    void *p = 0, *pen = 0; REAL e = d - width;
    GdipCreatePath(0, &p); GdipAddPathEllipse(p, cx - e / 2, cy - e / 2, e, e);
    GdipCreatePen1(c, width, 2, &pen); GdipDrawPath(g, pen, p);
    GdipDeletePen(pen); GdipDeletePath(p);
}
static void *roundPen(DWORD c, REAL width) {
    void *pen = 0; GdipCreatePen1(c, width, 2, &pen); GdipSetPenStartCap(pen, 2 /*round*/); GdipSetPenEndCap(pen, 2); return pen;
}
// A gradient across a box, left to right or top to bottom, through stops[] at at[] (0 to 1).
static void *lineBrush(REAL x, REAL y, REAL w, REAL h, int vertical, const DWORD *stops, const REAL *at, int n) {
    RECTF r = {x - 1, y - 1, w + 2, h + 2}; void *b = 0;
    GdipCreateLineBrushFromRect(&r, stops[0], stops[n - 1], vertical, 3 /*tile, flipped: no seam at the edges*/, &b);
    if (n > 2) GdipSetLinePresetBlend(b, stops, at, n);
    return b;
}
static void fillRoundV(void *g, REAL x, REAL y, REAL w, REAL h, REAL r, DWORD top, DWORD bottom) {
    DWORD s[2] = {top, bottom}; void *b = lineBrush(x, y, w, h, 1, s, 0, 2), *p = newRound(x, y, w, h, r);
    GdipFillPath(g, b, p);
    GdipDeleteBrush(b); GdipDeletePath(p);
}
// Light: an ellipse that fades from its middle to nothing at its edge, through
// stops[] (colours from the edge, at 0, to the middle, at 1).
static void light(void *g, REAL cx, REAL cy, REAL rx, REAL ry, const DWORD *stops, const REAL *at, int n) {
    void *p = 0, *b = 0; int one = 1;
    GdipCreatePath(0, &p); GdipAddPathEllipse(p, cx - rx, cy - ry, 2 * rx, 2 * ry);
    GdipCreatePathGradientFromPath(p, &b);
    GdipSetPathGradientCenterColor(b, stops[n - 1]);
    GdipSetPathGradientSurroundColorsWithCount(b, stops, &one);
    GdipSetPathGradientPresetBlend(b, stops, at, n);
    GdipFillPath(g, b, p);
    GdipDeleteBrush(b); GdipDeletePath(p);
}
// The falloff of a blur (a bell curve), from the edge to the middle.
static const REAL BLUR_AT[5] = {0, .25f, .5f, .75f, 1};
static const int BLUR_CURVE[5] = {0, 17, 46, 82, 100};
static void blurStops(DWORD *s, COLORREF c, int alpha) { for (int i = 0; i < 5; i++) s[i] = argb(c, alpha * BLUR_CURVE[i] / 100); }
// A soft glow of `c`, `alpha` strong in the middle.
static void glow(void *g, REAL cx, REAL cy, REAL rx, REAL ry, COLORREF c, int alpha) {
    DWORD s[5]; blurStops(s, c, alpha); light(g, cx, cy, rx, ry, s, BLUR_AT, 5);
}
// A rounded rectangle blurred by `blur` (like a CSS box-shadow).
static void blurRound(void *g, REAL x, REAL y, REAL w, REAL h, REAL r, REAL blur, COLORREF c, int alpha) {
    void *p = newRound(x - blur, y - blur, w + 2 * blur, h + 2 * blur, r + blur), *b = 0;
    DWORD s[5]; int one = 1; blurStops(s, c, alpha);
    GdipCreatePathGradientFromPath(p, &b);
    GdipSetPathGradientCenterColor(b, s[4]);
    GdipSetPathGradientSurroundColorsWithCount(b, s, &one);
    REAL fx = (w - 2 * blur) / (w + 2 * blur), fy = (h - 2 * blur) / (h + 2 * blur);
    GdipSetPathGradientFocusScales(b, fx > 0 ? fx : 0, fy > 0 ? fy : 0);
    GdipSetPathGradientPresetBlend(b, s, BLUR_AT, 5);
    GdipFillPath(g, b, p);
    GdipDeleteBrush(b); GdipDeletePath(p);
}
// The lit top edge of a raised shape (CSS inset 0 1px 0 white), fading down its sides.
static void sheen(void *g, REAL x, REAL y, REAL w, REAL h, REAL r, int alpha) {
    DWORD s[3] = {ARGB(alpha, 255, 255, 255), ARGB(0, 255, 255, 255), ARGB(0, 255, 255, 255)}; REAL at[3] = {0, .5f, 1};
    void *b = lineBrush(x, y, w, h, 1, s, at, 3), *pen = 0, *p = newRound(x + .5f, y + .5f, w - 1, h - 1, r - .5f);
    GdipCreatePen2(b, 1, 2, &pen); GdipDrawPath(g, pen, p);
    GdipDeletePen(pen); GdipDeleteBrush(b); GdipDeletePath(p);
}
// A tick, as in a checked box: in a circle `d` wide around (cx, cy).
static void tick(void *g, REAL cx, REAL cy, REAL d, DWORD ink, REAL width) {
    REAL u = d / 24; void *pen = roundPen(ink, width);
    GdipDrawLine(g, pen, cx - 5.5f * u, cy + .5f * u, cx - 1.8f * u, cy + 4.2f * u);
    GdipDrawLine(g, pen, cx - 1.8f * u, cy + 4.2f * u, cx + 5.8f * u, cy - 4.4f * u);
    GdipDeletePen(pen);
}
// The status sign: a lit ball in the state's colour, glowing, with a dark tick, "!",
// "i" or a line (turned off) - the editor's notices have the same.
static void drawOrb(void *g, RECT r) {
    COLORREF tone = statusTone();
    REAL d = (REAL)(r.right - r.left), cx = r.left + d / 2, cy = r.top + d / 2, u = d / 24;
    glow(g, cx, cy, d * 1.35f, d * 1.35f, tone, 130);
    fillCircle(g, cx, cy, d * 1.33f, argb(tone, 36));
    void *p = 0, *b = 0;
    GdipCreatePath(0, &p); GdipAddPathEllipse(p, cx - d / 2, cy - d / 2, d, d);
    GdipCreatePathGradientFromPath(p, &b);
    PTF lit = {cx, cy - d * .22f}; GdipSetPathGradientCenterPoint(b, &lit);
    DWORD s[3] = {argb(tone, 255), argb(tone, 255), argb(mix(tone, RGB(255, 255, 255), 55), 255)}; REAL at[3] = {0, .38f, 1};
    GdipSetPathGradientPresetBlend(b, s, at, 3);
    GdipFillPath(g, b, p);
    GdipDeleteBrush(b); GdipDeletePath(p);
    DWORD ink = ARGB(255, 11, 11, 13); REAL pw = 2.6f * u;
    if (statusKind == 1) tick(g, cx, cy, d, ink, pw);
    else if (statusKind == 3) { void *pen = roundPen(ink, pw); GdipDrawLine(g, pen, cx - 5 * u, cy, cx + 5 * u, cy); GdipDeletePen(pen); }
    else {
        int warn = statusKind == 2; void *pen = roundPen(ink, pw);
        GdipDrawLine(g, pen, cx, cy + (warn ? -6 : -1) * u, cx, cy + (warn ? 1.5f : 6) * u);
        GdipDeletePen(pen);
        fillCircle(g, cx, cy + (warn ? 5.6f : -5.4f) * u, 3.1f * u, ink);
    }
}
// The app icon's pixel art (pack.py), `px` screen pixels to a pixel: crisp at any size.
static void drawGamepad(HANDLE dc, int x, int y, int px) {
    for (int row = 0; row < 16; row++) for (int col = 0; col < 16; ) {
        char k = iconArt[row][col]; int run = 1;
        while (col + run < 16 && iconArt[row][col + run] == k) run++;
        int i = 0; while (iconKeys[i] && iconKeys[i] != k) i++;
        if (iconKeys[i] && iconRGBA[i][3]) {
            HANDLE b = CreateSolidBrush(RGB(iconRGBA[i][0], iconRGBA[i][1], iconRGBA[i][2]));
            RECT r = {x + col * px, y + row * px, x + (col + run) * px, y + (row + 1) * px}; FillRect(dc, &r, b);
            DeleteObject(b);
        }
        col += run;
    }
}
static void drawCard(void *g, RECT c) {
    REAL x = (REAL)c.left, y = (REAL)c.top, w = (REAL)(c.right - c.left), h = (REAL)(c.bottom - c.top), r = (REAL)S(12);
    fillRoundV(g, x, y, w, h, r, ARGB(246, 26, 26, 28), ARGB(246, 20, 20, 22));
    strokeRound(g, x, y, w, h, r, ARGB(22, 255, 255, 255), (REAL)max2(1, S(1)));
    DWORD s[3] = {ARGB(0, 255, 255, 255), ARGB(26, 255, 255, 255), ARGB(0, 255, 255, 255)}; REAL at[3] = {0, .5f, 1};
    void *b = lineBrush(x + r, y + 1, w - 2 * r, 1, 0, s, at, 3);
    GdipFillRectangle(g, b, x + r, y + max2(1, S(1)), w - 2 * r, 1);
    GdipDeleteBrush(b);
}

// Everything that stays put while the mouse moves, for the window's size `w` x `h`.
static void paintCanvas(int w, int h) {
    HANDLE screen = GetDC(mainWnd);
    if (!canvasBmp || w != canvasW || h != canvasH) {
        if (canvasBmp) DeleteObject(canvasBmp);
        canvasBmp = CreateCompatibleBitmap(screen, w, h); canvasW = w; canvasH = h;
    }
    HANDLE dc = CreateCompatibleDC(screen), old = SelectObject(dc, canvasBmp);
    ReleaseDC(mainWnd, screen);
    RECT all = {0, 0, w, h}; FillRect(dc, &all, bgBrush);
    void *g = gfx(dc);
    REAL W_ = (REAL)w, H_ = (REAL)h;
    // the editor's backdrop: warm light low on the right, violet low on the left
    glow(g, W_, H_, W_ * .8f, H_ * .55f, RGB(255, 106, 61), 18);
    glow(g, 0, H_, W_ * .62f, H_ * .5f, RGB(162, 89, 255), 15);
    // the website's warm light behind the gamepad, and a wide wash of it under the header
    int px = (gamepad.right - gamepad.left) / 16;
    REAL gx = gamepad.left + 8.0f * px, gy = gamepad.top + 7.5f * px, under = gamepad.top + 12.0f * px; // the middle and the bottom of the drawn gamepad
    glow(g, gx + S(150), gy, (REAL)S(320), (REAL)S(54), RGB(255, 106, 61), 18);
    DWORD warm[4] = {ARGB(0, 162, 89, 255), ARGB(18, 162, 89, 255), ARGB(44, 255, 70, 110), ARGB(104, 255, 140, 70)}; REAL warmAt[4] = {0, .3f, .54f, 1};
    light(g, gx, gy + S(4), gx, (REAL)S(50), warm, warmAt, 4);
    glow(g, gx, under + S(3), (REAL)S(44), (REAL)S(9), RGB(255, 150, 80), 120); // it floats over the light
    // a thin line in the website's gradient under the header, fading out at both ends
    if (hairline.right) {
        REAL hx = (REAL)hairline.left, hy = (REAL)hairline.top, hw = (REAL)(hairline.right - hairline.left), hh = (REAL)(hairline.bottom - hairline.top);
        glow(g, hx + hw * .45f, hy + hh / 2, hw * .45f, (REAL)S(7), RGB(255, 106, 61), 34);
        DWORD s[6] = {ARGB(0, 255, 179, 64), ARGB(200, 255, 179, 64), ARGB(220, 255, 106, 61), ARGB(205, 255, 61, 119), ARGB(170, 162, 89, 255), ARGB(0, 162, 89, 255)};
        REAL at[6] = {0, .14f, .4f, .64f, .86f, 1};
        void *b = lineBrush(hx, hy, hw, hh, 0, s, at, 6);
        GdipFillRectangle(g, b, hx, hy, hw, hh);
        GdipDeleteBrush(b);
    }
    for (int i = 0; i < cardCount; i++) drawCard(g, cards[i]);
    // the status card: the state's colour in its corner and along its edge, like the editor's notices
    if (cardCount && statusRow.right) {
        RECT c = cards[0]; COLORREF tone = statusTone();
        void *clip = newRound((REAL)c.left, (REAL)c.top, (REAL)(c.right - c.left), (REAL)(c.bottom - c.top), (REAL)S(12));
        GdipSetClipPath(g, clip, 0 /*replace*/);
        glow(g, (REAL)c.left, (REAL)c.top, (c.right - c.left) * .62f, (statusRow.bottom - statusRow.top) * 2.0f, tone, 38);
        REAL top = (REAL)(statusRow.top + S(14)), tall = (REAL)(statusRow.bottom - statusRow.top - S(28));
        if (tall < S(12)) { top -= (S(12) - tall) / 2; tall = (REAL)S(12); }
        blurRound(g, (REAL)(c.left - S(3)), top, (REAL)S(6), tall, (REAL)S(3), (REAL)S(10), tone, 120);
        fillRound(g, (REAL)(c.left - S(3)), top, (REAL)S(6), tall, (REAL)S(3), argb(tone, 255));
        GdipResetClip(g); GdipDeletePath(clip);
    }
    void *line = 0; GdipCreateSolidFill(ARGB(20, 255, 255, 255), &line);
    for (int i = 0; i < dividerCount; i++) {
        RECT d = dividers[i];
        GdipFillRectangle(g, line, (REAL)d.left, (REAL)d.top, (REAL)(d.right - d.left), (REAL)(d.bottom - d.top));
    }
    GdipDeleteBrush(line);
    if (statusIcon.right) drawOrb(g, statusIcon);
    // the main button's blue glow (it sits on top)
    if (primaryBtn && primaryPill.right) {
        RECT p = primaryPill; REAL pw = (REAL)(p.right - p.left), ph = (REAL)(p.bottom - p.top);
        blurRound(g, p.left + S(8), p.top + S(12), pw - S(16), ph - S(14), (ph - S(14)) / 2, (REAL)S(12), C.accent, 150);
    }
    // the glowing dot before "Key layout", as the editor marks its sections
    if (sectionDot.right) {
        REAL d = (REAL)(sectionDot.right - sectionDot.left), cx = sectionDot.left + d / 2, cy = sectionDot.top + d / 2;
        glow(g, cx, cy, d * 1.5f, d * 1.5f, C.dot, 190);
        fillCircle(g, cx, cy, d, argb(C.dot, 255));
    }
    GdipDeleteGraphics(g);
    if (px) drawGamepad(dc, gamepad.left, gamepad.top, px);
    SelectObject(dc, old); DeleteDC(dc);
    if (canvasBrush) DeleteObject(canvasBrush);
    canvasBrush = CreatePatternBrush(canvasBmp);
}
// A child window's piece of the canvas, as its background.
static void canvasUnder(HANDLE dc, HANDLE child, int w, int h) {
    RECT all = {0, 0, w, h}; PT p = {0, 0};
    MapWindowPoints(child, mainWnd, &p, 1);
    SetBrushOrgEx(dc, -p.x, -p.y, 0);
    FillRect(dc, &all, canvasBrush ? canvasBrush : bgBrush);
}
static void paintWindow(HANDLE w) {
    PAINTSTRUCT ps; HANDLE dc = BeginPaint(w, &ps);
    SetBrushOrgEx(dc, 0, 0, 0);
    FillRect(dc, &ps.rc, canvasBrush ? canvasBrush : bgBrush);
    EndPaint(w, &ps);
}

// ---- wrapped text, and the footer's keys as keycaps
static const WCHAR *const CAP_LABEL[3] = {L"Tab", L"F9", L"`"};
static int isAsciiLetter(WCHAR c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'); }
// A keycap at t[i] (0 Tab, 1 F9, 2 backtick; -1 for none), and how many characters
// it stands for: brackets around the backtick go with it.
static int capAt(const WCHAR *t, int i, int n, int *len) {
    int afterLetter = i > 0 && isAsciiLetter(t[i - 1]);
    if (!afterLetter && i + 3 <= n && t[i] == 'T' && t[i + 1] == 'a' && t[i + 2] == 'b' && !(i + 3 < n && isAsciiLetter(t[i + 3]))) { *len = 3; return 0; }
    if (!afterLetter && i + 2 <= n && t[i] == 'F' && t[i + 1] == '9' && !(i + 2 < n && t[i + 2] >= '0' && t[i + 2] <= '9')) { *len = 2; return 1; }
    if ((t[i] == '(' || t[i] == 0xFF08) && i + 2 < n && t[i + 1] == '`' && (t[i + 2] == ')' || t[i + 2] == 0xFF09)) { *len = 3; return 2; }
    if (t[i] == '`') { *len = 1; return 2; }
    return -1;
}
// Chinese and Japanese break between any two characters, except before closing
// punctuation and after opening punctuation.
static int isWide(WCHAR c) { return (c >= 0x2E80 && c <= 0x9FFF) || (c >= 0xF900 && c <= 0xFAFF) || (c >= 0xFF00 && c <= 0xFF60); }
static int inSet(const WCHAR *set, WCHAR c) { for (; *set; set++) if (*set == c) return 1; return 0; }
static int noBreakBetween(WCHAR a, WCHAR b) {
    return inSet(L"\x3001\x3002\xFF0C\xFF0E\x30FB\xFF1A\xFF1B\xFF1F\xFF01\xFF09\x300D\x300F\x3011\x3015\x3009\x300B\x30FC\x2026,.;:!?)", b)
        || inSet(L"\xFF08\x300C\x300E\x3010\x3014\x3008\x300A(", a);
}
static int textWidth(HANDLE dc, const WCHAR *s, int n) { SZ z = {0, 0}; if (n > 0) GetTextExtentPoint32W(dc, s, n, &z); return z.cx; }
static int capHeight(void) { return S(18); }
static int capWidth(HANDLE dc, int k) {
    HANDLE old = SelectObject(dc, fontKey); int w = textWidth(dc, CAP_LABEL[k], k == 2 ? 1 : (int)(k ? 2 : 3)); SelectObject(dc, old);
    return max2(S(20), w + S(12));
}
// A small keycap like the website's: dark, lit along its top, its bottom edge in the
// key's colour on the website's key map (green: menus; violet: the mod's own keys).
static void drawCap(HANDLE dc, int k, int x, int y, int w, int h) {
    COLORREF tone = k == 0 ? RGB(108, 194, 127) : RGB(166, 140, 240);
    REAL X = (REAL)x, Y = (REAL)y, W_ = (REAL)w, H_ = (REAL)h, r = (REAL)S(5), edge = (REAL)max2(1, S(2)), one = (REAL)max2(1, S(1));
    void *g = gfx(dc);
    glow(g, X + W_ / 2, Y + H_ - one, W_ / 2 + S(4), (REAL)S(5), tone, 70);
    fillRound(g, X, Y + one, W_, H_, r, ARGB(190, 0, 0, 0));
    fillRound(g, X, Y, W_, H_, r, argb(tone, 220));
    fillRound(g, X, Y, W_, H_ - edge, r, ARGB(36, 255, 255, 255));
    fillRoundV(g, X, Y + one, W_, H_ - edge - one, r, ARGB(255, 46, 46, 50), ARGB(255, 32, 32, 35));
    if (k == 2) { // the backtick: a short stroke (the font's is a speck at this size)
        REAL u = dpi / 96.0f, cx = X + W_ / 2, cy = Y + (H_ - edge) / 2;
        void *pen = roundPen(argb(C.text, 255), 2.1f * u);
        GdipDrawLine(g, pen, cx - 1.5f * u, cy - 2.6f * u, cx + 1.3f * u, cy + 1.4f * u);
        GdipDeletePen(pen);
    }
    GdipDeleteGraphics(g);
    if (k == 2) return;
    HANDLE old = SelectObject(dc, fontKey); COLORREF oldInk = SetTextColor(dc, C.text);
    RECT tr = {x, y, x + w, y + h - (int)edge};
    DrawTextW(dc, CAP_LABEL[k], -1, &tr, 0x1 /*DT_CENTER*/ | 0x4 /*DT_VCENTER*/ | 0x20 /*DT_SINGLELINE*/ | 0x800 /*DT_NOPREFIX*/);
    SetTextColor(dc, oldInk); SelectObject(dc, old);
}
// The room beside a keycap at t[j] (`len` characters) where text touches it.
static int capRoom(const WCHAR *t, int j, int n, int len) {
    return (j > 0 && t[j - 1] != ' ' ? S(3) : 0) + (j + len < n && t[j + len] != ' ' ? S(3) : 0);
}
// Text in lines `width` wide, laid out here: it breaks at spaces, and between Chinese
// or Japanese characters (Windows' own wrapping breaks Russian words anywhere). With
// `caps`, Tab, F9 and ` are keycaps. With `draw`, draws it from `top` in the DC's font
// and colour, `lineH` apart (0: the font's height). Returns where it ends.
static int flowText(HANDLE dc, const WCHAR *t, int n, int width, int top, int draw, int caps, int lineH) {
    int capH = capHeight(), cw[3] = {0, 0, 0};
    if (caps) for (int k = 0; k < 3; k++) cw[k] = capWidth(dc, k);
    SZ m = {0, 0}; GetTextExtentPoint32W(dc, L"Ag", 2, &m);
    if (!lineH) lineH = m.cy;
    int space = textWidth(dc, L" ", 1), x = 0, y = top, i = 0;
    while (i < n) {
        if (t[i] == '\n') { x = 0; y += lineH; i++; continue; }
        if (x == 0) while (i < n && t[i] == ' ') i++;
        if (i >= n) break;
        // the next piece that can't be broken: where it ends, and how wide it is
        int j = i, w = 0, fit = i; // fit: where to cut a piece longer than a line
        for (;;) {
            int len, k = caps ? capAt(t, j, n, &len) : -1;
            if (k >= 0) { w += capRoom(t, j, n, len) + cw[k]; j += len; }
            else { w += textWidth(dc, t + j, 1); j++; }
            if (w <= width) fit = j;
            if (j >= n || t[j] == ' ' || t[j] == '\n') break;
            if ((isWide(t[j - 1]) || isWide(t[j])) && !noBreakBetween(t[j - 1], t[j])) break;
        }
        if (x > 0 && x + w > width) { x = 0; y += lineH; }
        if (w > width && fit > i) { j = fit; w = width; } // longer than a line: cut it
        int end = j, spaces = 0;
        while (j < n && t[j] == ' ') j++, spaces++;
        if (draw) { // text runs and keycaps
            int at = x, run = i, ty = y + (lineH - m.cy) / 2;
            for (int q = i; caps && q < end; ) {
                int len, k = capAt(t, q, end, &len);
                if (k < 0) { q++; continue; }
                if (q > run) { TextOutW(dc, at, ty, t + run, q - run); at += textWidth(dc, t + run, q - run); }
                int room = capRoom(t, q, n, len), before = q > 0 && t[q - 1] != ' ' ? S(3) : 0;
                drawCap(dc, k, at + before, y + (lineH - capH) / 2, cw[k], capH);
                at += room + cw[k];
                q += len; run = q;
            }
            if (end > run) TextOutW(dc, at, ty, t + run, end - run);
        }
        x += w + spaces * space;
        i = j;
    }
    return y + lineH;
}
// The status: its first sentence as a headline, the rest under it in grey, like the
// editor's notices. Where the rest starts (n: it's one sentence).
static int statusSplit(const WCHAR *t, int n) {
    for (int i = 0; i + 1 < n; i++) {
        int end = t[i] == 0x3002 /*。*/ || t[i] == 0xFF01 || t[i] == 0xFF1F || ((t[i] == '.' || t[i] == '!' || t[i] == '?') && t[i + 1] == ' ');
        if (!end) continue;
        int j = i + 1; while (j < n && t[j] == ' ') j++;
        return j;
    }
    return n;
}
// The labels drawn here (owner-drawn, so screen readers still have their text): the
// tagline, the status, the Record logs hint and the footer. Lays out label `c` in
// `width` (and with `draw`, draws it); returns its height.
static int flowLabel(HANDLE c, HANDLE dc, int width, int draw) {
    static WCHAR t[1024]; int n = GetWindowTextW(c, t, 1024), h;
    HANDLE old = SelectObject(dc, c == footerWnd ? fontSmall : fontNormal);
    SetTextColor(dc, C.text2);
    if (c == footerWnd) h = flowText(dc, t, n, width, 0, draw, 1, S(21));
    else if (c == statusWnd) {
        int k = statusSplit(t, n);
        SelectObject(dc, fontStatus); SetTextColor(dc, C.text);
        h = flowText(dc, t, k, width, 0, draw, 0, 0);
        if (k < n) { SelectObject(dc, fontNormal); SetTextColor(dc, C.text2); h = flowText(dc, t + k, n - k, width, h + S(2), draw, 0, 0); }
    } else h = flowText(dc, t, n, width, 0, draw, 0, 0);
    SelectObject(dc, old);
    return h;
}
static int labelHeight(HANDLE c, int width, int least) {
    HANDLE dc = GetDC(c); int h = flowLabel(c, dc, width, 0); ReleaseDC(c, dc);
    return max2(h, S(least));
}
typedef struct { UINT type, id, item, action, state; HANDLE wnd, dc; RECT rc; U64 data; } DRAWITEM;
static void drawLabel(DRAWITEM *d) {
    RECT r = d->rc; int w = r.right - r.left, h = r.bottom - r.top;
    HANDLE mem = CreateCompatibleDC(d->dc), bmp = CreateCompatibleBitmap(d->dc, w, h), oldBmp = SelectObject(mem, bmp);
    canvasUnder(mem, d->wnd, w, h);
    SetBkMode(mem, 1);
    flowLabel(d->wnd, mem, w, 1);
    BitBlt(d->dc, r.left, r.top, w, h, mem, 0, 0, 0x00CC0020 /*SRCCOPY*/);
    SelectObject(mem, oldBmp); DeleteObject(bmp); DeleteDC(mem);
}

// ---- buttons and the key layout choices (owner-drawn), with the hover state Windows doesn't give them
static int isRadio(HANDLE c) { return c == layoutBtn[0] || c == layoutBtn[1] || c == layoutBtn[2]; }
static void drawButton(DRAWITEM *d) {
    RECT r = d->rc; int wdt = r.right - r.left, hgt = r.bottom - r.top;
    HANDLE mem = CreateCompatibleDC(d->dc), bmp = CreateCompatibleBitmap(d->dc, wdt, hgt), oldBmp = SelectObject(mem, bmp);
    canvasUnder(mem, d->wnd, wdt, hgt);
    int off = (d->state & 4) != 0, down = (d->state & 1) != 0 && !off, hover = hovered == d->wnd && !off;
    int focus = (d->state & 0x10) && !(d->state & 0x200);
    WCHAR text[256]; int n = GetWindowTextW(d->wnd, text, 256);
    void *g = gfx(mem);
    REAL room = (REAL)FOCUS_ROOM, x = room, y = room, w = wdt - 2 * room, h = hgt - 2 * room, rr;
    COLORREF ink = off ? C.textOff : C.text; HANDLE font = fontNormal;
    RECT tr; UINT how = 0x800 /*DT_NOPREFIX*/ | 0x20 /*DT_SINGLELINE*/ | 0x4 /*DT_VCENTER*/ | 0x8000 /*DT_END_ELLIPSIS*/;
    if (isRadio(d->wnd)) {
        // a row; the chosen one is lit: a blue ring with a soft glow and a filled tick
        int on = radioOn[d->wnd == layoutBtn[0] ? 0 : d->wnd == layoutBtn[1] ? 1 : 2] && !off;
        rr = (REAL)S(9);
        if (on) {
            blurRound(g, x, y, w, h, rr, room, C.accent, 110);
            fillRound(g, x, y, w, h, rr, argb(mix(C.accent, RGB(24, 24, 26), down ? 12 : hover ? 20 : 16), 255));
            strokeRound(g, x, y, w, h, rr, argb(hover ? C.accentHi : C.accent, 255), S(3) / 2.0f);
        } else if (hover || down) fillRound(g, x, y, w, h, rr, ARGB(down ? 24 : 15, 255, 255, 255));
        REAL dd = (REAL)S(18), mx = x + S(8) + dd / 2, my = y + h / 2;
        if (on) {
            glow(g, mx, my, dd * 1.1f, dd * 1.1f, C.accent, 110);
            fillCircle(g, mx, my, dd, argb(C.accent, 255));
            tick(g, mx, my, dd * 1.1f, ARGB(255, 255, 255, 255), S(18) / 9.0f);
        } else ringCircle(g, mx, my, dd, ARGB(off ? 40 : hover ? 150 : 96, 255, 255, 255), S(3) / 2.0f);
        RECT t = {(int)(mx + dd / 2) + S(12), 0, (int)(x + w) - S(10), hgt}; tr = t;
    } else {
        // a pill: blue for the thing to do, dark otherwise; it sinks a little when pressed
        int primary = d->wnd == primaryBtn && !off;
        if (down) { x += 1; y += 1; w -= 2; h -= 2; }
        rr = h / 2;
        if (primary) {
            fillRound(g, x, y, w, h, rr, argb(down ? C.accentDown : hover ? C.accentHi : C.accent, 255));
            sheen(g, x, y, w, h, rr, 64);
            ink = RGB(255, 255, 255); font = fontStrong;
        } else {
            fillRound(g, x, y, w, h, rr, ARGB(off ? 9 : down ? 48 : hover ? 37 : 24, 255, 255, 255));
            strokeRound(g, x, y, w, h, rr, ARGB(off ? 12 : 26, 255, 255, 255), 1);
            if (!off) sheen(g, x, y, w, h, rr, 16);
        }
        RECT t = {(int)x + S(12), (int)y, (int)(x + w) - S(12), (int)(y + h)}; tr = t;
        how |= 0x1 /*DT_CENTER*/;
        // recording logs: a red dot before the label
        if (d->wnd == recordBtn && recording && !off) {
            HANDLE oldF = SelectObject(mem, font); int tw = textWidth(mem, text, n); SelectObject(mem, oldF);
            REAL dot = (REAL)S(8), start = x + (w - (dot + S(8) + tw)) / 2;
            glow(g, start + dot / 2, y + h / 2, dot * 1.6f, dot * 1.6f, RGB(255, 69, 58), 160);
            fillCircle(g, start + dot / 2, y + h / 2, dot, ARGB(255, 255, 69, 58));
            tr.left = (int)(start + dot) + S(8); tr.right = tr.left + tw + 1; how &= ~0x1u;
        }
    }
    if (focus) strokeRound(g, 0, 0, (REAL)wdt, (REAL)hgt, rr + room, ARGB(255, 255, 255, 255), (REAL)S(2)); // 2 px, a little outside
    GdipDeleteGraphics(g);
    HANDLE oldFont = SelectObject(mem, font);
    SetBkMode(mem, 1); SetTextColor(mem, ink);
    DrawTextW(mem, text, n, &tr, how);
    SelectObject(mem, oldFont);
    BitBlt(d->dc, r.left, r.top, wdt, hgt, mem, 0, 0, 0x00CC0020);
    SelectObject(mem, oldBmp); DeleteObject(bmp); DeleteDC(mem);
}
static LRESULT hoverProc(HANDLE w, UINT msg, WPARAM wp, LPARAM lp) {
    if (msg == 0x200 /*WM_MOUSEMOVE*/ && hovered != w) {
        HANDLE old = hovered; hovered = w;
        if (old) InvalidateRect(old, 0, 0);
        InvalidateRect(w, 0, 0);
        TRACKMOUSEEVENT t = {sizeof(t), 2 /*TME_LEAVE*/, w, 0}; TrackMouseEvent(&t);
    }
    if (msg == 0x2A3 /*WM_MOUSELEAVE*/ && hovered == w) { hovered = 0; InvalidateRect(w, 0, 0); }
    if (msg == 0x203 /*WM_LBUTTONDBLCLK*/) msg = 0x201; // two quick clicks are two clicks
    if (msg == 0x14 /*WM_ERASEBKGND*/) return 1;
    return CallWindowProcW(buttonProc, w, msg, wp, lp);
}

// ---------------------------------------------------------------- layout
//
// Every control is placed for the text it has now (a translation can be longer):
// buttons as wide as their labels, text wrapped, and the window as big as needed.
static const DWORD WINDOW_STYLE = 0x02CA0000; // caption, system menu, minimize box; children drawn over the cards
static int measure(HANDLE c, int width, int *height) {
    WCHAR text[1024]; int n = GetWindowTextW(c, text, 1024);
    HANDLE dc = GetDC(c), old = SelectObject(dc, (HANDLE)SendMessageW(c, 0x31 /*WM_GETFONT*/, 0, 0));
    RECT r = {0, 0, width ? width : 4000, 0};
    DrawTextW(dc, text, n, &r, 0x400 /*DT_CALCRECT*/ | 0x800 /*DT_NOPREFIX*/ | (width ? 0x10 /*DT_WORDBREAK*/ : 0x20 /*DT_SINGLELINE*/));
    SelectObject(dc, old); ReleaseDC(c, dc);
    if (height) *height = r.bottom;
    return r.right;
}
static int buttonWidth(HANDLE c, int least) { int w = measure(c, 0, 0) + S(34); return w > S(least) ? w : S(least); }
static int textHeight(HANDLE c, int width, int least) { int h; measure(c, width, &h); return h > S(least) ? h : S(least); }
// (Without redrawing: layout() may try a few widths, then redraws everything.)
static void place(HANDLE c, int x, int y, int w, int h) { SetWindowPos(c, 0, x, y, w, h, 0x4 /*SWP_NOZORDER*/ | 0x10 /*SWP_NOACTIVATE*/ | 0x8 /*SWP_NOREDRAW*/); }
// A button's control is a little bigger than the button: its focus ring goes around it.
static void placeButton(HANDLE c, int x, int y, int w, int h) { place(c, x - FOCUS_ROOM, y - FOCUS_ROOM, w + 2 * FOCUS_ROOM, h + 2 * FOCUS_ROOM); }
static void card(int x, int top, int w, int bottom) { RECT r = {x, top, x + w, bottom}; cards[cardCount++] = r; }
static int divider(int x, int y, int w) { int t = max2(1, S(1)); RECT r = {x, y, x + w, y + t}; dividers[dividerCount++] = r; return t; }
// Places everything for cards `want` wide (or wider, for the buttons); returns the
// window's height and the cards' width.
#define MARGIN S(24)
static int arrange(int want, int *cards_) {
    cardCount = dividerCount = 0;
    int m = MARGIN, px = S(18), py = S(14), gap = S(8), bh = S(32);
    int install = buttonWidth(installBtn, 112), remove = buttonWidth(uninstallBtn, 96), onOff = buttonWidth(onOffBtn, 96), browse = buttonWidth(browseBtn, 96);
    int editor = buttonWidth(editorBtn, 0), load = buttonWidth(loadBtn, 0), settings = buttonWidth(settingsBtn, 0);
    int record = buttonWidth(recordBtn, 0) + (recording ? S(16) : 0);
    int inner = want; // the cards' width
    inner = max2(inner, 2 * px + editor + load + settings + 2 * gap);
    inner = max2(inner, 2 * px + S(24) + S(14) + S(200) + S(16) + install);
    int x = m, cx = m + px, cw = inner - 2 * px, y = S(18);
    // header: the gamepad in its light, the wordmark, what it is
    int art = S(4), padW = 16 * art, padH = 9 * art; // the icon's rows 3 to 11 have the gamepad
    int tx = cx + padW + S(20), tw = inner - px - padW - S(20);
    int titleH = titlePixel ? S(32) : textHeight(titleWnd, 0, 24), ink = titlePixel ? S(28) : titleH * 4 / 5; // ink: down to the baseline
    int ih = labelHeight(introWnd, tw, 18), block = ink + S(7) + ih, head = max2(padH, block), wordTop = y + (head - block) / 2;
    place(titleWnd, tx, wordTop, tw, titleH < ink + S(7) ? titleH : ink + S(7));
    place(introWnd, tx, wordTop + ink + S(7), tw, ih);
    RECT pad = {cx, y + (head - padH) / 2 - 3 * art, cx + padW, y + (head - padH) / 2 + 13 * art}; gamepad = pad;
    y += head + S(10);
    RECT hl = {m, y, m + inner, y + max2(1, S(1))}; hairline = hl;
    y += S(11);
    // card 1: the state and what to do, the game folder, turn off / uninstall
    int top = y; y += py;
    int orb = S(24), sx = cx + orb + S(14), sw = cw - orb - S(14) - S(16) - install;
    int sh = labelHeight(statusWnd, sw, 20), row = max2(sh, bh);
    RECT icon = {cx, y + (row - orb) / 2, cx + orb, y + (row - orb) / 2 + orb}; statusIcon = icon;
    place(statusWnd, sx, y + (row - sh) / 2, sw, sh);
    int ix = cx + cw - install, iy = y + (row - bh) / 2;
    placeButton(installBtn, ix, iy, install, bh);
    RECT installPill = {ix, iy, ix + install, iy + bh}, none = {0, 0, 0, 0};
    primaryPill = primaryBtn == installBtn ? installPill : none;
    y += row + py;
    RECT band = {x, top, x + inner, y}; statusRow = band;
    y += divider(cx, y, cw) + py - S(2);
    int lh = textHeight(folderLabel, 0, 18), ph = textHeight(pathWnd, 0, 16);
    place(folderLabel, cx, y, cw - browse - S(16), lh);
    place(pathWnd, cx, y + lh, cw - browse - S(16), ph);
    placeButton(browseBtn, cx + cw - browse, y + (lh + ph - bh) / 2, browse, bh);
    if (primaryBtn == browseBtn) { RECT bp = {cx + cw - browse, y + (lh + ph - bh) / 2, cx + cw, y + (lh + ph - bh) / 2 + bh}; primaryPill = bp; }
    y += lh + ph + py - S(2);
    y += divider(cx, y, cw) + py - S(4);
    placeButton(onOffBtn, cx, y, onOff, bh); placeButton(uninstallBtn, cx + onOff + gap, y, remove, bh);
    if (primaryBtn == onOffBtn) { RECT onPill = {cx, y, cx + onOff, y + bh}; primaryPill = onPill; }
    y += bh + py - S(4); card(x, top, inner, y);
    // card 2: the key layout
    y += S(12); top = y; y += py;
    int kh = textHeight(layoutLabel, 0, 20);
    RECT dot = {cx, y + kh / 2 - S(4), cx + S(8), y + kh / 2 + S(4)}; sectionDot = dot;
    place(layoutLabel, cx + S(18), y, cw - S(18), kh);
    y += kh + S(8);
    for (int i = 0; i < 3; i++) { placeButton(layoutBtn[i], cx - S(8), y, cw + S(16), bh); y += bh + S(6); }
    y += S(2);
    y += divider(cx, y, cw) + py;
    placeButton(editorBtn, cx, y, editor, bh); placeButton(loadBtn, cx + editor + gap, y, load, bh);
    placeButton(settingsBtn, cx + editor + load + 2 * gap, y, settings, bh);
    y += bh + py; card(x, top, inner, y);
    // card 3: Record logs
    y += S(12); top = y; y += py;
    int hw = cw - record - S(16), hh = labelHeight(recordHint, hw, 18); row = max2(hh, bh);
    place(recordHint, cx, y + (row - hh) / 2, hw, hh);
    placeButton(recordBtn, cx + cw - record, y + (row - bh) / 2, record, bh);
    y += row + py; card(x, top, inner, y);
    // what to remember, with the keys as keycaps
    y += S(11);
    int fh = labelHeight(footerWnd, inner - S(8), 18); place(footerWnd, m + S(4), y, inner - S(8), fh); y += fh + S(13);
    *cards_ = inner;
    return y;
}
static int cardsWidth; // chosen for the language (0: choose again)
static void layout(void) {
    if (!mainWnd || !footerWnd) return;
    int inner, h;
    if (!cardsWidth) { // a long translation: wider, when that makes the window a good deal shorter
        int cost = 1 << 30;
        for (int w = S(584); w <= S(720); w += S(34)) {
            h = arrange(w, &inner);
            int c = h + (inner - S(584)) / 3;
            if (c < cost) { cost = c; cardsWidth = inner; }
        }
    }
    h = arrange(cardsWidth, &inner);
    paintCanvas(inner + 2 * MARGIN, h);
    RECT r = {0, 0, inner + 2 * MARGIN, h}; AdjustWindowRect(&r, WINDOW_STYLE, 0);
    SetWindowPos(mainWnd, 0, 0, 0, r.right - r.left, r.bottom - r.top, 0x2 /*SWP_NOMOVE*/ | 0x4 | 0x10);
    RedrawWindow(mainWnd, 0, 0, 0x1 /*RDW_INVALIDATE*/ | 0x4 /*RDW_ERASE*/ | 0x80 /*RDW_ALLCHILDREN*/);
}
static void setStatus(const char *text) { setText(statusWnd, text); layout(); }

static void refresh(void) {
    int have = gameDir[0] != 0, state = have ? installState(gameDir) : NOT_INSTALLED;
    if (have) setPath(pathWnd, gameDir); else setText(pathWnd, T("(not found)"));
    const char *text = !have ? T("Game not found in Steam or XboxGames. Click Browse and pick Dungeons*.exe (in Dungeons\\Binaries) or Dungeons.exe.")
        : state == INSTALLED_LATEST ? T("Installed and up to date. Start (or restart) the game to use it.")
        : state == INSTALLED_OLDER ? T("An older version is installed. Click Update.")
        : state == OTHER_DLL ? T("The game folder has a different xinput1_4.dll (another mod?). Install replaces it and keeps a copy as xinput1_4.dll.other.")
        : state == TURNED_OFF ? T("Turned off: the game starts without wasdmod. Your layouts are kept; click Turn on to use it again.")
        : T("Not installed yet.");
    setText(statusWnd, text);
    statusKind = !have || state == OTHER_DLL ? 2 : state == INSTALLED_LATEST ? 1 : state == TURNED_OFF ? 3 : 0;
    installAccent = have && state != INSTALLED_LATEST && state != TURNED_OFF; // blue while it's the thing to do
    primaryBtn = !have ? browseBtn : installAccent ? installBtn : state == TURNED_OFF ? onOffBtn : 0; // (Browse while there's no game, Turn on while it's off)
    recording = have && recordingOn(gameDir);
    setText(installBtn, state == INSTALLED_OLDER ? T("Update") : state == INSTALLED_LATEST || state == TURNED_OFF ? T("Reinstall") : T("Install"));
    EnableWindow(installBtn, have);
    int installed = have && (state == INSTALLED_LATEST || state == INSTALLED_OLDER || state == TURNED_OFF);
    EnableWindow(uninstallBtn, installed);
    setText(onOffBtn, state == TURNED_OFF ? T("Turn on") : T("Turn off"));
    EnableWindow(onOffBtn, installed);
    setText(recordBtn, recording ? T("Stop and save logs") : T("Record logs"));
    EnableWindow(recordBtn, have);
    EnableWindow(editorBtn, have);
    EnableWindow(loadBtn, installed);
    EnableWindow(settingsBtn, installed);
    // The layout in use (the newest settings file) is the checked one.
    char active[PATHLEN] = "", own[PATHLEN], ownName[PATHLEN];
    int hasOwn = have && findFiles(gameDir, "wasdmod*.txt", own, 0);
    if (installed) activeSettings(gameDir, active);
    const char *name = baseName(active);
    int current = !installed ? -1 : sameText(name, "default.txt") ? 0 : sameText(name, "author.txt") ? 1 : 2;
    if (current == 2 || hasOwn) fill(ownName, sizeof(ownName), T("Your own ({file})"), current == 2 ? name : baseName(own));
    else scpy(ownName, sizeof(ownName), T("Your own (none saved yet)"));
    setText(layoutBtn[2], ownName);
    for (int i = 0; i < 3; i++) {
        radioOn[i] = i == current;
        InvalidateRect(layoutBtn[i], 0, 0);
        EnableWindow(layoutBtn[i], installed && (i < 2 || hasOwn));
    }
    layout();
}
// All the window's text, in the current language (again after a change in the editor).
static void applyTexts(void) {
    cardsWidth = 0; // the window's width suits the language's text
    setText(mainWnd, T("wasdmod - Minecraft Dungeons II controller mod"));
    setText(introWnd, T("Play Minecraft Dungeons II with WASD, mouse and keys, as a controller."));
    setText(folderLabel, T("Game folder"));
    setText(browseBtn, T("Browse..."));
    setText(layoutLabel, T("Key layout"));
    setText(layoutBtn[0], T("Official layout (the game's own keys)"));
    setText(layoutBtn[1], T("Recommended"));
    setText(editorBtn, T("Edit key layout..."));
    setText(loadBtn, T("Load layout file..."));
    setText(settingsBtn, T("Open settings file"));
    setText(uninstallBtn, T("Uninstall"));
    setText(recordHint, T("Something not working? Record logs, play until it happens, then stop: a report file for GitHub."));
    setText(footerWnd, T("Layout changes reach a running game within a second; restart it after installing. In game: Tab opens the menu wheel, F9 shows the key list, backtick (`) turns the mod off and on."));
    refresh();
}

// A file to open, as an ANSI path (what the rest of the setup uses).
static int pickFile(const char *title, const char *kind, const char *pattern, const char *initialDir, char *out) {
    static WCHAR filter[600], file[PATHLEN], dir[PATHLEN], head[300]; // static: no stack probe without the C runtime
    const char *parts[] = {kind, pattern, T("All files"), "*.*"};
    int n = 0;
    for (int i = 0; i < 4; i++) { int k = MultiByteToWideChar(65001, 0, parts[i], -1, filter + n, 599 - n); if (k <= 0) return 0; n += k; }
    filter[n] = 0;
    file[0] = 0; dir[0] = 0;
    if (!MultiByteToWideChar(65001, 0, title, -1, head, 300)) head[0] = 0;
    if (initialDir && !MultiByteToWideChar(0 /*CP_ACP*/, 0, initialDir, -1, dir, PATHLEN)) dir[0] = 0;
    OPENFILENAMEW o; memset(&o, 0, sizeof(o));
    o.size = sizeof(o); o.owner = mainWnd; o.filter = filter; o.filterIndex = 1; o.file = file; o.maxFile = PATHLEN;
    o.initialDir = dir[0] ? dir : 0; o.title = head; o.flags = 0x1000 | 0x800 | 0x4 | 0x8; // must exist, hide read-only, keep directory
    if (!GetOpenFileNameW(&o)) return 0;
    BOOL lost = 0;
    return WideCharToMultiByte(0 /*CP_ACP*/, 0, file, -1, out, PATHLEN, 0, &lost) > 0 && !lost;
}

static void onCommand(int id) {
    char p[PATHLEN];
    if (id == ID_BROWSE) {
        if (!pickFile(T("Find Minecraft Dungeons II"), T("Minecraft Dungeons II (*.exe)"), "*.exe", 0, p)) return;
        char dir[PATHLEN];
        if (dirFromPick(p, dir)) scpy(gameDir, sizeof(gameDir), dir);
        else ask(T("That isn't the Minecraft Dungeons II folder. Pick Dungeons*.exe (in Dungeons\\Binaries) or Dungeons.exe."), 0x30);
    } else if (id == ID_INSTALL) {
        int r = install(gameDir, 0);
        if (r == ERR_OTHER_DLL && ask(T("The game folder already has a different xinput1_4.dll (probably another mod). Replace it? A copy is kept as xinput1_4.dll.other."), 0x4 | 0x30) == 6) r = install(gameDir, 1);
        if (r == OK) ask(T("Installed. Start (or restart) Minecraft Dungeons II.\n\nIn game: WASD moves, Tab opens the menu wheel (the game's own key, S, moves you now), F9 shows the key list, and the backtick key (`) turns the mod off and on."), 0x40);
        else if (r != ERR_OTHER_DLL) ask(T(errorText[r]), 0x30);
    } else if (id == ID_ONOFF) {
        int on = installState(gameDir) == TURNED_OFF, r = turnOn(gameDir, on);
        if (r != OK) ask(T("Couldn't rename xinput1_4.dll in the game folder. Close the game, or run this setup as administrator."), 0x30);
        else ask(on ? T("Turned on. Start (or restart) the game to use wasdmod again.")
                    : T("Turned off. From the next game start, the game runs without wasdmod; your layouts are kept.\n\n(In a running game, the backtick key (`) turns it off right away.)"), 0x40);
    } else if (id == ID_RECORD) {
        if (!recordingOn(gameDir)) {
            if (setRecording(gameDir, 1) != OK) ask(T(errorText[ERR_WRITE]), 0x30);
            else ask(T("Recording logs. Play until the problem happens, then come back here and click Stop and save logs.\n\nIf the game is running, recording starts within a second; otherwise it starts with the game. Nothing you type is recorded."), 0x40);
        } else {
            setRecording(gameDir, 0);
            if (writeReport(gameDir, p) != OK) ask(T("Couldn't save the logs on the Desktop."), 0x30);
            else {
                char args[PATHLEN + 16] = "/select,\""; cat(args, sizeof(args), p); cat(args, sizeof(args), "\"");
                ShellExecuteA(mainWnd, "open", "explorer.exe", args, 0, 1);
                char msg[PATHLEN + 900];
                fill(msg, sizeof(msg), T("Saved {file} on your Desktop. It has the mod's log, your key layout and your Windows version; nothing you type is recorded.\n\nOpen GitHub to report the problem (attach the file)?"), baseName(p));
                if (ask(msg, 0x4 | 0x40) == 6) ShellExecuteA(mainWnd, "open", "https://github.com/Wanzho/mcd2-wasd/issues/new", 0, 0, 1);
            }
        }
    } else if (id == ID_UNINSTALL) {
        int removeLayout = findLayouts(gameDir, 0, 0) && ask(T("Also delete your saved key layouts (author.txt, wasdmod*.txt)?"), 0x4 | 0x20) == 6;
        int r = uninstall(gameDir, removeLayout);
        ask(r == OK ? T("Uninstalled. The game is back to how it was.") : T(errorText[r]), r == OK ? 0x40 : 0x30);
    } else if (id == ID_DEFAULT || id == ID_RECOMMENDED || id == ID_OWN) {
        int r = useLayout(gameDir, id - ID_DEFAULT);
        if (r != OK) ask(T(errorText[r]), 0x30);
        refresh();
        if (r == OK) setStatus(T("Key layout changed. A running game switches to it within a second."));
        return;
    } else if (id == ID_EDITOR) {
        if (openEditor()) { setStatus(T("The key layout editor opened in its own window. Its Save to game button writes straight into the game folder while this window stays open.")); return; }
        // No local server (blocked?): the editor as a file, which downloads layouts instead.
        join(p, gameDir, "Key Layout Editor.html");
        if (!sameAs(p, payloadEditor, sizeof(payloadEditor)) && !writeAll(p, payloadEditor, sizeof(payloadEditor))) { ask(T(errorText[ERR_WRITE]), 0x30); return; }
        ShellExecuteA(mainWnd, "open", p, 0, 0, 1);
        setStatus(T("The key layout editor opened in your browser. Pick or create a layout there and click Download file; then click \"Load layout file\" here."));
        return;
    } else if (id == ID_LOAD) {
        char downloads[PATHLEN] = "";
        if (GetEnvironmentVariableA("USERPROFILE", downloads, 300)) cat(downloads, sizeof(downloads), "\\Downloads");
        if (!pickFile(T("Load a key layout"), T("Key layout (*.ini;*.txt)"), "*.ini;*.txt", downloads[0] ? downloads : 0, p)) return;
        DWORD n; char *b = readAll(p, &n);
        int valid = b && (contains(b, n, "[Buttons]") || contains(b, n, "[Move]"));
        // Keep the editor's names (author.txt, default.txt, wasdmod-MMDDYY.txt); anything else becomes wasdmod.txt.
        const char *name = baseName(p); unsigned nl = slen(name);
        int keep = (nl > 11 && sameTextN(name, "wasdmod", 7) && sameText(name + nl - 4, ".txt")) || sameText(name, "author.txt") || sameText(name, "default.txt");
        char dest[PATHLEN]; join(dest, gameDir, keep ? name : "wasdmod.txt");
        if (!valid) ask(T("That file isn't a key layout (it has no [Buttons] or [Move] section)."), 0x30);
        else if (!writeAll(dest, b, n)) ask(T(errorText[ERR_WRITE]), 0x30);
        else ask(T("Key layout loaded. A running game switches to it within a second."), 0x40);
        if (b) HeapFree(GetProcessHeap(), 0, b);
    } else if (id == ID_SETTINGS) {
        activeSettings(gameDir, p);
        char quoted[PATHLEN + 2] = "\""; cat(quoted, sizeof(quoted), p); cat(quoted, sizeof(quoted), "\"");
        ShellExecuteA(mainWnd, "open", "notepad.exe", quoted, 0, 1);
        return;
    } else return;
    refresh();
}

static HANDLE control(const char *cls, DWORD style, int id, HANDLE font) {
    HANDLE c = CreateWindowExW(0, W(cls), W(""), 0x50000000 /*WS_CHILD|WS_VISIBLE*/ | style,
                               0, 0, 10, 10, mainWnd, (HANDLE)(U64)id, GetModuleHandleA(0), 0);
    SendMessageW(c, 0x30 /*WM_SETFONT*/, (WPARAM)font, 1);
    if (cls[0] == 'B') { WNDPROC old = (WNDPROC)SetWindowLongPtrW(c, -4 /*GWLP_WNDPROC*/, (LONG_PTR)hoverProc); if (!buttonProc) buttonProc = old; }
    return c;
}
#define LABEL 0x80     // SS_NOPREFIX: & is just &
#define BUTTON 0x1000B // WS_TABSTOP | BS_OWNERDRAW

static LRESULT wndProc(HANDLE w, UINT msg, WPARAM wp, LPARAM lp) {
    if (msg == 0x01) { // WM_CREATE
        mainWnd = w;
        themeTitleBar();
        titleWnd = control("STATIC", LABEL, 0, fontTitle); setText(titleWnd, "wasdmod");
        introWnd = control("STATIC", 0x0D /*SS_OWNERDRAW: wrapped here*/, 0, fontNormal);
        statusWnd = control("STATIC", 0x0D /*SS_OWNERDRAW: a headline and the rest*/, ID_STATUS, fontStatus);
        installBtn = control("BUTTON", BUTTON, ID_INSTALL, fontStrong); // (measured in the blue button's bold)
        folderLabel = control("STATIC", LABEL, 0, fontNormal);
        pathWnd = control("STATIC", LABEL | 0x8000 /*SS_PATHELLIPSIS*/, ID_PATH, fontSmall);
        browseBtn = control("BUTTON", BUTTON, ID_BROWSE, fontStrong);
        onOffBtn = control("BUTTON", BUTTON, ID_ONOFF, fontStrong);
        uninstallBtn = control("BUTTON", BUTTON, ID_UNINSTALL, fontNormal);
        layoutLabel = control("STATIC", LABEL, 0, fontStatus);
        layoutBtn[0] = control("BUTTON", BUTTON, ID_DEFAULT, fontNormal);
        layoutBtn[1] = control("BUTTON", BUTTON, ID_RECOMMENDED, fontNormal);
        layoutBtn[2] = control("BUTTON", BUTTON, ID_OWN, fontNormal);
        editorBtn = control("BUTTON", BUTTON, ID_EDITOR, fontNormal);
        loadBtn = control("BUTTON", BUTTON, ID_LOAD, fontNormal);
        settingsBtn = control("BUTTON", BUTTON, ID_SETTINGS, fontNormal);
        recordHint = control("STATIC", 0x0D, 0, fontNormal);
        recordBtn = control("BUTTON", BUTTON, ID_RECORD, fontNormal);
        footerWnd = control("STATIC", 0x0D /*SS_OWNERDRAW: its keys are drawn as keycaps*/, 0, fontSmall);
        applyTexts();
        return 0;
    }
    if (msg == 0x111 /*WM_COMMAND*/ && (wp >> 16) == 0 /*BN_CLICKED*/) { onCommand((int)(wp & 0xFFFF)); return 0; }
    if (msg == 0x2B /*WM_DRAWITEM*/) { DRAWITEM *d = (DRAWITEM *)lp; if (d->type == 5 /*ODT_STATIC*/) drawLabel(d); else drawButton(d); return 1; }
    if (msg == 0x0F /*WM_PAINT*/) { paintWindow(w); return 0; }
    if (msg == 0x14 /*WM_ERASEBKGND*/) return 1;
    if (msg == 0x138 /*WM_CTLCOLORSTATIC*/) { // text, plain or grey, on its piece of the canvas
        HANDLE c = (HANDLE)lp, dc = (HANDLE)wp; PT p = {0, 0};
        MapWindowPoints(c, w, &p, 1); SetBrushOrgEx(dc, -p.x, -p.y, 0);
        SetBkMode(dc, 1 /*TRANSPARENT*/);
        SetTextColor(dc, c == introWnd || c == pathWnd || c == recordHint ? C.text2 : C.text);
        return (LRESULT)(canvasBrush ? canvasBrush : bgBrush);
    }
    if (msg == WM_EDITOR_SAVED) {
        refresh();
        char text[PATHLEN + 400]; fill(text, sizeof(text), T("Saved {file} from the key layout editor. A running game switches to it within a second."), savedName);
        setStatus(text);
        return 0;
    }
    if (msg == WM_LANGUAGE) { applyTexts(); return 0; } // picked in the key layout editor
    if (msg == 0x02) { PostQuitMessage(0); return 0; } // WM_DESTROY
    return DefWindowProcW(w, msg, wp, lp);
}

// A font by name, or the next one when this Windows doesn't have it.
static HANDLE makeFont(int px, int weight, const char *face, const char *fallback) {
    HANDLE f = CreateFontA(-S(px), 0, 0, 0, weight, 0, 0, 0, 1, 0, 0, 5 /*CLEARTYPE*/, 0, face);
    char got[64] = ""; HANDLE dc = GetDC(0), old = SelectObject(dc, f); GetTextFaceA(dc, sizeof(got), got); SelectObject(dc, old); ReleaseDC(0, dc);
    if (fallback && !sameText(got, face)) { DeleteObject(f); f = CreateFontA(-S(px), 0, 0, 0, weight, 0, 0, 0, 1, 0, 0, 5, 0, fallback); }
    return f;
}
// The website's pixel font for the wordmark ("Mojang" by b.tenthousand, CC0; inside
// this exe), unsmoothed so its pixels stay sharp: 8 font pixels to the em, so `px`
// is a multiple of 8. 0 if Windows won't take it.
static HANDLE pixelFont(int px) {
    DWORD n = 0;
    if (!AddFontMemResourceEx(payloadPixelFont, sizeof(payloadPixelFont), 0, &n) || !n) return 0;
    HANDLE f = CreateFontA(-S(px), 0, 0, 0, 400, 0, 0, 0, 1 /*DEFAULT_CHARSET*/, 0, 0, 3 /*NONANTIALIASED*/, 0, "Mojang");
    char got[64] = ""; HANDLE dc = GetDC(0), old = SelectObject(dc, f); GetTextFaceA(dc, sizeof(got), got); SelectObject(dc, old); ReleaseDC(0, dc);
    if (!sameText(got, "Mojang")) { DeleteObject(f); return 0; }
    return f;
}

// ---------------------------------------------------------------- the key layout editor window
//
// "Edit key layout..." opens the editor in a window of its own: WebView2, the Edge
// engine Windows provides for apps, inside a plain window with wasdmod's icon. It
// shows the same page the local server serves (see servePage). Microsoft's
// WebView2Loader.dll (BSD license, see the README) travels inside this exe and is
// written to %LOCALAPPDATA%\wasdmod to start it. Without WebView2 the editor opens
// as an Edge or Chrome app window instead.
//
// WebView2 is COM: each object starts with its method table. The method numbers
// below are from WebView2.h (SDK 1.0.4258.31); the handlers WebView2 calls back
// are small static objects.
