typedef HRESULT (*MP)(void *, void *);
typedef HRESULT (*MPP)(void *, void *, void *);
typedef HRESULT (*MI)(void *, int);
typedef HRESULT (*MRECT)(void *, RECT);
typedef HRESULT (*MCOLOR)(void *, WV2COLOR);
typedef HRESULT (*MQI)(void *, const GUID *, void **);
